package com.ironsgrotto;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.ui.overlay.components.ComponentConstants;

@ConfigGroup(IronsGrottoConfig.GROUP)
public interface IronsGrottoConfig extends Config
{
	String GROUP = "ironsgrotto";
	String DEFAULT_API_BASE_URL = "https://ironsgrotto.xyz";

	@ConfigSection(
		name = "Notifications",
		description = "What the plugin shows in game",
		position = 1
	)
	String notificationsSection = "notifications";

	@ConfigSection(
		name = "Overlay",
		description = "SOTW/BOTW standings on the game screen",
		position = 2
	)
	String overlaySection = "overlay";

	@ConfigSection(
		name = "Advanced",
		description = "For plugin development",
		position = 3,
		closedByDefault = true
	)
	String advancedSection = "advanced";

	@ConfigItem(
		keyName = "chatFeedback",
		name = "Chat messages",
		description = "Confirm recorded drops, log slots and pets in chat",
		section = notificationsSection,
		position = 0
	)
	default boolean chatFeedback()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showMotd",
		name = "Message of the day",
		description = "Show the clan's message of the day in chat when you log in",
		section = notificationsSection,
		position = 1
	)
	default boolean showMotd()
	{
		return true;
	}

	@ConfigItem(
		keyName = "debug",
		name = "Debug messages",
		description = "Show every server response in chat",
		section = notificationsSection,
		position = 2
	)
	default boolean debug()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showEventOverlay",
		name = "Show SOTW/BOTW overlay",
		description = "Standings on the game screen. Hold Alt to drag it, and drag an edge to resize; taller shows more rows",
		section = overlaySection,
		position = 0
	)
	default boolean showEventOverlay()
	{
		return false;
	}

	@Alpha
	@ConfigItem(
		keyName = "overlayBackground",
		name = "Background",
		description = "The overlay's background colour; lower the opacity to see the game through it",
		section = overlaySection,
		position = 1
	)
	default Color overlayBackground()
	{
		return ComponentConstants.STANDARD_BACKGROUND_COLOR;
	}

	@ConfigItem(
		keyName = "apiBaseUrl",
		name = "Server URL",
		description = "For local development only",
		section = advancedSection
	)
	default String apiBaseUrl()
	{
		return DEFAULT_API_BASE_URL;
	}

}

package com.ironsgrotto;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.inject.Provides;
import com.ironsgrotto.api.ApiException;
import com.ironsgrotto.api.GrottoApiClient;
import com.ironsgrotto.api.TokenStore;
import com.ironsgrotto.api.model.MeResponse;
import com.ironsgrotto.api.model.PluginPolicy;
import com.ironsgrotto.api.model.Registration;
import com.ironsgrotto.ledger.LedgerRecorder;
import com.ironsgrotto.outbox.Outbox;
import com.ironsgrotto.outbox.OutboxEntry;
import com.ironsgrotto.outbox.OutboxStore;
import com.ironsgrotto.progress.CollectionLogButton;
import com.ironsgrotto.progress.CollectionLogSync;
import com.ironsgrotto.progress.ProgressCollector;
import com.ironsgrotto.progress.ProgressSync;
import com.ironsgrotto.progress.ProgressUploader;
import com.ironsgrotto.session.AccountIdentity;
import com.ironsgrotto.session.AccountSession;
import com.ironsgrotto.tracker.ChatEventTracker;
import com.ironsgrotto.tracker.LootEventTracker;
import com.ironsgrotto.ui.ClanEventOverlay;
import com.ironsgrotto.ui.CollapsibleSection;
import com.ironsgrotto.ui.GrottoPanel;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.time.Clock;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletionException;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.Data;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootTrackerPlugin;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Irons Grotto Clan",
	internalName = "irons-grotto",
	legacyDataDirectory = "irons-grotto",
	description = "Irons Grotto clan rank, SOTW/BOTW standings and event tracking",
	tags = {"clan", "irons grotto", "rank", "bingo", "events"}
)
public class IronsGrottoPlugin extends Plugin
{
	private static final String EVENTS_PATH = GrottoApiClient.API_PREFIX + "/events";
	private static final long FLUSH_INTERVAL_SECONDS = 5;
	private static final long REFRESH_CHECK_SECONDS = 30;
	/**
	 * The message of the day's text: the blue from the clan logo (the site's
	 * {@code --ig-tertiary}). The logo's green and teal vanish on the opaque
	 * chat box and its indigo on the transparent one; this blue reads on both.
	 */
	private static final Color MOTD_COLOUR = new Color(0x2F8FE0);
	/** Standings asked for: enough for the tallest overlay. The panel shows five. */
	private static final int EVENT_STANDINGS = 25;
	/** How often the overlay's standings refresh; the server caches Temple for 3 minutes. */
	private static final long OVERLAY_REFRESH_MS = TimeUnit.MINUTES.toMillis(3);

	@Inject
	private IronsGrottoConfig config;

	@Inject
	private AccountSession session;

	@Inject
	private GrottoApiClient api;

	@Inject
	private TokenStore tokens;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClanEventOverlay eventOverlay;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private SyncExecutor executor;

	@Inject
	private Gson gson;

	@Inject
	private EventBus eventBus;

	@Inject
	private LedgerRecorder recorder;

	@Inject
	private ChatEventTracker chatTracker;

	@Inject
	private LootEventTracker lootTracker;



	@Inject
	private ProgressSync progressSync;

	@Inject
	private ProgressUploader progressUploader;

	@Inject
	private ProgressCollector progressCollector;

	@Inject
	private CollectionLogSync collectionLogSync;

	@Inject
	private CollectionLogButton collectionLogButton;


	private GrottoPanel panel;
	private NavigationButton navButton;
	private Outbox outbox;
	private ScheduledFuture<?> flushTask;
	private ScheduledFuture<?> refreshTask;

	private volatile PluginPolicy policy = new PluginPolicy();
	private volatile long lastRefreshAt;
	private volatile long lastEventsAt;
	/** The account the message of the day was shown to this login; cleared at logout. */
	private volatile String motdShownTo;
	/** Names the site said are registered, this session. */
	private final Map<String, Registration> registrations = new java.util.concurrent.ConcurrentHashMap<>();

	@Provides
	IronsGrottoConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(IronsGrottoConfig.class);
	}

	@Override
	protected void startUp() throws IOException
	{
		executor.start();
		panel = new GrottoPanel(this::siteUrl, itemManager, new CollapsibleSection.Store()
		{
			// Hidden config keys, not settings: which panel blocks are folded.
			@Override
			public boolean isCollapsed(String id)
			{
				return Boolean.TRUE.equals(configManager.getConfiguration(IronsGrottoConfig.GROUP, "collapsed." + id, Boolean.class));
			}

			@Override
			public void setCollapsed(String id, boolean collapsed)
			{
				configManager.setConfiguration(IronsGrottoConfig.GROUP, "collapsed." + id, collapsed);
			}
		});
		panel.setOnTokenEntered(this::checkToken);
		tokens.open(getPluginDirectory().join("tokens.json"), gson);
		tokens.setOnCleared(this::tokenRejected);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Irons Grotto")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(eventOverlay);

		OutboxStore store = new OutboxStore(getPluginDirectory().join("outbox.json"), gson);
		outbox = new Outbox(this::sendEvents, store, Clock.systemUTC(), this::chat);

		recorder.attach(outbox, entry ->
		{
			panel.addRecentEvent(entry);
			panel.setPendingCount(outbox.size());
		});
		eventBus.register(chatTracker);
		eventBus.register(lootTracker);
		eventBus.register(progressSync);
		eventBus.register(collectionLogSync);
		eventBus.register(collectionLogButton);
		collectionLogSync.setOnMessage(this::say);
		collectionLogButton.startUp();

		progressUploader.setOnSynced(result ->
		{
			// Points may have moved; show the new standing.
			refresh();
		});

		flushTask = executor.scheduleWithFixedDelay(this::flushOutbox, FLUSH_INTERVAL_SECONDS, FLUSH_INTERVAL_SECONDS, TimeUnit.SECONDS);
		refreshTask = executor.scheduleWithFixedDelay(this::refreshIfStale, REFRESH_CHECK_SECONDS, REFRESH_CHECK_SECONDS, TimeUnit.SECONDS);

		panel.showLootTrackerOff(!progressCollector.isLootTrackerEnabled());

		// Enabling the plugin while already logged in: the next game tick picks
		// the account up and refreshes.
		refreshPanelState();
	}

	@Override
	protected void shutDown()
	{
		eventBus.unregister(chatTracker);
		eventBus.unregister(lootTracker);
		eventBus.unregister(progressSync);
		eventBus.unregister(collectionLogSync);
		eventBus.unregister(collectionLogButton);
		collectionLogButton.shutDown();
		recorder.detach();
		clientToolbar.removeNavigation(navButton);
		overlayManager.remove(eventOverlay);
		eventOverlay.setStatus(null);
		if (flushTask != null)
		{
			flushTask.cancel(false);
		}
		if (refreshTask != null)
		{
			refreshTask.cancel(false);
		}
		session.clear();
		executor.stop();
		panel = null;
		outbox = null;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (session.poll())
		{
			refresh();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			if (session.clear() && state == GameState.LOGIN_SCREEN)
			{
				panel.showLoggedOut();
				eventOverlay.setStatus(null);
				// The next login shows the message of the day again.
				motdShownTo = null;
			}
		}
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		GrottoPanel current = panel;
		if (event.getPlugin() instanceof LootTrackerPlugin && current != null)
		{
			current.showLootTrackerOff(!progressCollector.isLootTrackerEnabled());
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!IronsGrottoConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}


		if ("showEventOverlay".equals(event.getKey()) && config.showEventOverlay())
		{
			AccountIdentity identity = session.getIdentity();
			if (identity != null && tokens.has(identity))
			{
				refreshEvents(identity);
			}
		}

		if ("apiBaseUrl".equals(event.getKey()))
		{
			// Everything learned from the old server is about the old server.
			// Requests already read the setting each time; the panel's links
			// do too. Only these remembered answers need forgetting.
			registrations.clear();
			policy = new PluginPolicy();
			outbox.resume();
			refresh();
		}
	}

	/**
	 * A token pasted into the panel, for the account logged in now. Tried
	 * with the server first and saved only if it is accepted, which also
	 * binds it to this account.
	 */
	private void checkToken(String token)
	{
		AccountIdentity identity = session.getIdentity();
		if (identity == null)
		{
			return;
		}

		api.checkToken(identity, token)
			.thenAccept(me ->
			{
				tokens.set(identity, token);
				// Anything waiting for a token goes now.
				outbox.resume();
				refresh();
			})
			.exceptionally(error ->
			{
				Throwable cause = error instanceof CompletionException && error.getCause() != null ? error.getCause() : error;
				panel.showNoToken(identity.getRsn(), tokenCheckMessage(cause));
				return null;
			});
	}

	private static String tokenCheckMessage(Throwable cause)
	{
		if (cause instanceof ApiException && ((ApiException) cause).isUnauthorized())
		{
			return "Token not accepted. Check it's copied in full, or get a new one.";
		}
		return cause.getMessage() != null ? cause.getMessage() : "Can't reach the Irons Grotto server.";
	}

	/**
	 * Whether a token-less account is on the site, so the panel sends it to
	 * the right place. Asked once per name per session; a failed lookup
	 * leaves the default ("Get a token") in place.
	 */
	private void lookUpRegistration(String rsn)
	{
		Registration known = registrations.get(rsn);
		if (known != null)
		{
			panel.showTokenSource(rsn, known.sendsToJoin(), known.getLinks());
			return;
		}

		api.checkRegistration(rsn)
			.thenAccept(registration ->
			{
				// Only a "yes" is kept: a new member who joins mid-session is
				// asked again next time and sent to "Get a token".
				if (registration.isRegistered())
				{
					registrations.put(rsn, registration);
				}
				panel.showTokenSource(rsn, registration.sendsToJoin(), registration.getLinks());
			})
			.exceptionally(error ->
			{
				log.debug("Could not check whether {} is registered", rsn, error);
				return null;
			});
	}

	/** The server will never take this account's token; ask for another. */
	private void tokenRejected(AccountIdentity account, String reason)
	{
		chat(reason);
		if (account.equals(session.getIdentity()))
		{
			panel.showNoToken(account.getRsn(), reason);
			lookUpRegistration(account.getRsn());
		}
	}

	public PluginPolicy getPolicy()
	{
		return policy;
	}

	private void refresh()
	{
		lastRefreshAt = System.currentTimeMillis();

		AccountIdentity identity = refreshPanelState();
		if (identity == null)
		{
			return;
		}

		api.getMe(identity)
			.thenAccept(me ->
			{
				policy = me.getPolicy() != null ? me.getPolicy() : new PluginPolicy();
				panel.showMe(me);
				showMotdOnce(identity, me.getMotd());
			})
			.exceptionally(this::handleRefreshError);

		refreshEvents(identity);

		// Non-members get null; an older server 404s. Either way, no section.
		api.getUpgradePath(identity)
			.thenAccept(path -> panel.showUpgradePath(path))
			.exceptionally(error ->
			{
				log.debug("Could not load next unlocks", error);
				panel.showUpgradePath(null);
				return null;
			});

		// An older server has no news (404): the section stays hidden.
		api.getNews(identity)
			.thenAccept(news -> panel.showNews(news))
			.exceptionally(error ->
			{
				log.debug("Could not load clan news", error);
				panel.showNews(null);
				return null;
			});

		// An older server has no top loots (404): the section stays hidden.
		api.getTopLoot(identity)
			.thenAccept(loots -> panel.showTopLoots(loots))
			.exceptionally(error ->
			{
				log.debug("Could not load top loots", error);
				panel.showTopLoots(null);
				return null;
			});
	}

	/** SOTW/BOTW standings for the panel and the overlay. */
	private void refreshEvents(AccountIdentity identity)
	{
		lastEventsAt = System.currentTimeMillis();
		api.getClanEvents(identity, EVENT_STANDINGS)
			.thenAccept(events ->
			{
				panel.showEvents(events);
				eventOverlay.setStatus(events);
			})
			.exceptionally(error ->
			{
				// The overlay keeps the last standings it had.
				log.debug("Could not load clan events", error);
				return null;
			});
	}

	/** Shows the logged-out or unlinked state, and returns who to load data for. */
	private AccountIdentity refreshPanelState()
	{
		AccountIdentity identity = session.getIdentity();
		if (identity == null)
		{
			panel.showLoggedOut();
			return null;
		}
		if (!tokens.has(identity))
		{
			panel.showNoToken(identity.getRsn(), null);
			lookUpRegistration(identity.getRsn());
			return null;
		}
		return identity;
	}

	private Void handleRefreshError(Throwable error)
	{
		Throwable cause = error instanceof CompletionException && error.getCause() != null ? error.getCause() : error;

		if (cause instanceof ApiException && ((ApiException) cause).isTokenDead())
		{
			// Already handled: the token is gone and the panel asks for another.
			return null;
		}

		if (cause instanceof ApiException && ((ApiException) cause).isUpgradeRequired())
		{
			// Nothing recorded is lost: the outbox waits for the update.
			panel.showError(cause.getMessage());
		}
		else
		{
			panel.showError(cause.getMessage() != null ? cause.getMessage() : "Can't reach the Irons Grotto server.");
		}

		if (config.debug())
		{
			chat("Refresh failed: " + cause.getMessage());
		}
		return null;
	}

	private void refreshIfStale()
	{
		long intervalMs = TimeUnit.SECONDS.toMillis(Math.max(60, policy.getPanelRefreshSeconds()));
		AccountIdentity identity = session.getIdentity();
		long now = System.currentTimeMillis();
		if (identity != null && now - lastRefreshAt >= intervalMs)
		{
			refresh();
		}
		else if (identity != null && config.showEventOverlay() && tokens.has(identity)
			&& now - lastEventsAt >= OVERLAY_REFRESH_MS)
		{
			// The overlay is on screen while playing, so its standings refresh
			// more often than the panel's.
			refreshEvents(identity);
		}
	}

	private void flushOutbox()
	{
		Outbox current = outbox;
		if (current == null)
		{
			return;
		}

		try
		{
			current.flush();
			progressUploader.flush();
		}
		catch (RuntimeException e)
		{
			// A scheduled task that throws is never run again.
			log.warn("Irons Grotto outbox flush failed", e);
		}

		GrottoPanel currentPanel = panel;
		if (currentPanel != null)
		{
			currentPanel.setPendingCount(current.size());
		}
	}

	private Outbox.SendResult sendEvents(AccountIdentity account, List<OutboxEntry> batch) throws ApiException
	{
		EventsResponse response = api.postBlocking(EVENTS_PATH, account, new EventsRequest(batch), EventsResponse.class);

		if (config.debug())
		{
			chat("Sent " + batch.size() + " events, " + response.getAccepted().size() + " accepted");
		}

		return new Outbox.SendResult(response.getAccepted(), response.getRejected(), response.getMessages());
	}

	private void chat(String message)
	{
		if (!config.chatFeedback() && !config.debug())
		{
			return;
		}
		say(message);
	}

	/**
	 * The message of the day, once per login per account: the first refresh
	 * after logging in shows it, a world hop does not. Tags are stripped, so
	 * whatever the server sends is shown as plain text.
	 */
	private void showMotdOnce(AccountIdentity identity, MeResponse.Motd motd)
	{
		if (motd == null || motd.getMessage() == null || !config.showMotd()
			|| identity.getAccountHash().equals(motdShownTo))
		{
			return;
		}
		motdShownTo = identity.getAccountHash();

		String formatted = new ChatMessageBuilder()
			.append(ChatColorType.NORMAL)
			.append("[Irons Grotto] ")
			// append(Color, text): plain append escapes tags, so a <col> tag
			// built by hand shows up as text in the chat box.
			.append(MOTD_COLOUR, Text.removeTags(motd.getMessage()))
			.build();

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(formatted)
			.build());
	}

	/** A chat line the member asked for (a button they pressed), whatever the chat setting. */
	private void say(String message)
	{
		String formatted = new ChatMessageBuilder()
			.append("[Irons Grotto] ")
			.append(message)
			.build();

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(formatted)
			.build());
	}

	private String siteUrl()
	{
		return config.apiBaseUrl().replaceAll("/+$", "");
	}

	/** Body of {@code POST /api/plugin/events}; the account travels in headers. */
	@Data
	static class EventsRequest
	{
		private final List<EventDto> events;

		EventsRequest(List<OutboxEntry> batch)
		{
			this.events = new ArrayList<>();
			for (OutboxEntry entry : batch)
			{
				events.add(new EventDto(entry.getId(), entry.getType(), entry.getOccurredAt(), entry.getPayload()));
			}
		}
	}

	@Data
	static class EventDto
	{
		private final String id;
		private final String type;
		private final String occurredAt;
		private final JsonObject payload;
	}

	@Data
	static class EventsResponse
	{
		private Set<String> accepted = new HashSet<>();
		private Map<String, String> rejected = new HashMap<>();
		private List<String> messages = new ArrayList<>();
	}
}

package com.ironsgrotto;

import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * The plugin's own background thread, for everything that talks to the
 * server.
 *
 * ⚠️ Not RuneLite's injected {@code ScheduledExecutorService}: that is one
 * thread shared by every plugin, and this plugin makes blocking HTTP calls
 * that can take seconds when the server is slow or unreachable. On the shared
 * thread that would stall everyone else's scheduled work. Nothing here ever
 * runs on the client thread either.
 */
@Slf4j
@Singleton
public class SyncExecutor
{
	private ScheduledExecutorService executor;

	public synchronized void start()
	{
		if (executor == null || executor.isShutdown())
		{
			executor = Executors.newSingleThreadScheduledExecutor(runnable ->
			{
				Thread thread = new Thread(runnable, "irons-grotto-sync");
				thread.setDaemon(true);
				return thread;
			});
		}
	}

	public synchronized void stop()
	{
		if (executor != null)
		{
			executor.shutdown();
			executor = null;
		}
	}

	public synchronized void execute(Runnable task)
	{
		submit(task);
	}

	/** @return the task's future, or a completed one if the plugin has stopped */
	public synchronized Future<?> submit(Runnable task)
	{
		if (executor == null)
		{
			return java.util.concurrent.CompletableFuture.completedFuture(null);
		}
		try
		{
			return executor.submit(logged(task));
		}
		catch (RejectedExecutionException e)
		{
			return java.util.concurrent.CompletableFuture.completedFuture(null);
		}
	}

	public synchronized ScheduledFuture<?> scheduleWithFixedDelay(Runnable task, long initialDelay, long delay, TimeUnit unit)
	{
		start();
		return executor.scheduleWithFixedDelay(logged(task), initialDelay, delay, unit);
	}

	/** A task that throws would otherwise silently cancel a repeating schedule. */
	private static Runnable logged(Runnable task)
	{
		return () ->
		{
			try
			{
				task.run();
			}
			catch (RuntimeException e)
			{
				log.warn("Irons Grotto background task failed", e);
			}
		};
	}
}

package com.ironsgrotto.api;

import lombok.Getter;

/** A request the server answered with an error, or could not be reached for. */
@Getter
public class ApiException extends Exception
{
	/** The server's machine-readable reason for refusing this token for this account. */
	public static final String ACCOUNT_NOT_YOURS = "account_not_yours";
	public static final String TOKEN_ACCOUNT_MISMATCH = "token_account_mismatch";

	/** HTTP status, or 0 when the server could not be reached. */
	private final int status;
	/** The server's error code, when it sent one. */
	private final String code;

	public ApiException(int status, String message)
	{
		this(status, message, null);
	}

	public ApiException(int status, String message, String code)
	{
		super(message);
		this.status = status;
		this.code = code;
	}

	public ApiException(String message, Throwable cause)
	{
		super(message, cause);
		this.status = 0;
		this.code = null;
	}

	/** Worth retrying later: network failures, rate limits and server errors. */
	public boolean isRetryable()
	{
		return status == 0 || status == 429 || status >= 500;
	}

	/** This plugin release is older than the server supports; the member must update. */
	public boolean isUpgradeRequired()
	{
		return status == 426;
	}

	/**
	 * Nothing is wrong with the data, only with this client: a bad token, an
	 * account it may not speak for, or an outdated release. Keep the data and
	 * wait for the member to fix it.
	 */
	public boolean isClientBlocked()
	{
		return status == 401 || status == 403 || status == 426;
	}

	/**
	 * This token can never speak for this account: the account is someone
	 * else's, or the token is bound to another account. The token is dropped.
	 */
	public boolean isTokenRejectedForAccount()
	{
		return ACCOUNT_NOT_YOURS.equals(code) || TOKEN_ACCOUNT_MISMATCH.equals(code);
	}

	/**
	 * The saved token will never work for this account: revoked or unknown
	 * (401), bound to another account, or the account is someone else's.
	 */
	public boolean isTokenDead()
	{
		return status == 401 || isTokenRejectedForAccount();
	}

	/** The token is missing, wrong or revoked. */
	public boolean isUnauthorized()
	{
		return status == 401;
	}
}

package com.ironsgrotto.api;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import com.ironsgrotto.IronsGrottoConfig;
import com.ironsgrotto.api.model.ClanEventStatus;
import com.ironsgrotto.api.model.ClanNews;
import com.ironsgrotto.api.model.MeResponse;
import com.ironsgrotto.api.model.Registration;
import com.ironsgrotto.api.model.TopLoot;
import com.ironsgrotto.api.model.UpgradePath;
import com.ironsgrotto.session.AccountIdentity;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * The only thing in the plugin that talks to the Irons Grotto server.
 *
 * Every request carries the account it speaks for and that account's plugin
 * token (see {@link TokenStore}). When the server says the token can never
 * speak for the account, the token is dropped here, in one place. Responses
 * use the backend's envelope, {@code {success, data}} or {@code {success, error}}.
 */
@Slf4j
@Singleton
public class GrottoApiClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	/**
	 * The API contract this release speaks. v1 routes only ever change in
	 * backward-compatible ways; a breaking change is a new version beside it.
	 */
	public static final String API_PREFIX = "/api/plugin/v1";

	/**
	 * Sent with every request. The server refuses releases older than its
	 * minimum with 426, which the plugin shows as "please update".
	 */
	public static final String PLUGIN_VERSION = "1.1.1";

	private final OkHttpClient http;
	private final Gson gson;
	private final IronsGrottoConfig config;
	private final TokenStore tokens;
	private final String userAgent;

	@Inject
	GrottoApiClient(OkHttpClient http, Gson gson, IronsGrottoConfig config, TokenStore tokens)
	{
		this(http, gson, config, tokens, "IronsGrottoPlugin/" + PLUGIN_VERSION);
	}

	protected GrottoApiClient(OkHttpClient http, Gson gson, IronsGrottoConfig config, TokenStore tokens, String userAgent)
	{
		this.http = http;
		this.gson = gson;
		this.config = config;
		this.tokens = tokens;
		this.userAgent = userAgent;
	}

	public CompletableFuture<MeResponse> getMe(AccountIdentity identity)
	{
		return getAsync(API_PREFIX + "/me", identity, MeResponse.class, null);
	}

	/**
	 * Tries a token the member has just pasted, before it is saved. Accepting
	 * it also binds it to this account on the server. A refusal leaves the
	 * saved token (if any) alone: it is this candidate that was refused.
	 */
	public CompletableFuture<MeResponse> checkToken(AccountIdentity identity, String candidate)
	{
		return getAsync(API_PREFIX + "/me", identity, MeResponse.class, candidate.trim());
	}

	/**
	 * Whether a name is on the site at all. Public: no token and no account
	 * headers, so it works before the member has a token.
	 */
	public CompletableFuture<Registration> checkRegistration(String rsn)
	{
		CompletableFuture<Registration> future = new CompletableFuture<>();
		HttpUrl base = HttpUrl.parse(config.apiBaseUrl());
		if (base == null)
		{
			future.completeExceptionally(new ApiException(0, "Invalid server URL: " + config.apiBaseUrl()));
			return future;
		}

		Request request = new Request.Builder()
			.url(base.newBuilder()
				.encodedPath(API_PREFIX + "/public/registration")
				.addQueryParameter("rsn", rsn)
				.build())
			.header("X-Plugin-Version", PLUGIN_VERSION)
			.header("User-Agent", userAgent)
			.get()
			.build();

		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				future.completeExceptionally(unreachable(call.request().url(), e));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (response)
				{
					Registration registration = parse(response, null, Registration.class, false);
					future.complete(registration != null ? registration : new Registration());
				}
				catch (ApiException e)
				{
					future.completeExceptionally(e);
				}
			}
		});

		return future;
	}


	/**
	 * The running SOTW/BOTW and the next one.
	 *
	 * @param standings how many standings rows to ask for; a server older than
	 *                  the parameter ignores it and sends five
	 */
	public CompletableFuture<ClanEventStatus> getClanEvents(AccountIdentity identity, int standings)
	{
		return getAsync(API_PREFIX + "/clan-events?standings=" + standings, identity, ClanEventStatus.class, null);
	}

	/**
	 * The member's next unlocks. Null data for an account that is not a ranked
	 * member; a 404 is an older server.
	 */
	public CompletableFuture<UpgradePath> getUpgradePath(AccountIdentity identity)
	{
		return getAsync(API_PREFIX + "/upgrade-path", identity, UpgradePath.class, null);
	}

	/** The clan's news, newest first. A 404 is an older server. */
	public CompletableFuture<List<ClanNews>> getNews(AccountIdentity identity)
	{
		return getAsync(API_PREFIX + "/news", identity, new TypeToken<List<ClanNews>>()
		{
		}.getType(), null);
	}

	/** The clan's most valuable drops in the server's last 24 hours. A 404 is an older server. */
	public CompletableFuture<List<TopLoot>> getTopLoot(AccountIdentity identity)
	{
		return getAsync(API_PREFIX + "/top-loot", identity, new TypeToken<List<TopLoot>>()
		{
		}.getType(), null);
	}

	/**
	 * Sends a JSON body and blocks for the reply. For background senders such
	 * as the outbox, which run off the client thread and need ordering.
	 */
	public <T> T postBlocking(String path, AccountIdentity identity, Object body, Type responseType)
		throws ApiException
	{
		Request request = requestBuilder(path, identity)
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();

		try (Response response = http.newCall(request).execute())
		{
			return parse(response, identity, responseType);
		}
		catch (IOException e)
		{
			throw unreachable(request.url(), e);
		}
	}

	/** Sends account progress; returns the server's reply. Blocking; background threads only. */
	public JsonObject putProgress(AccountIdentity identity, JsonObject progress) throws ApiException
	{
		Request request = requestBuilder(API_PREFIX + "/progress", identity)
			.put(RequestBody.create(JSON, gson.toJson(progress)))
			.build();

		try (Response response = http.newCall(request).execute())
		{
			return parse(response, identity, JsonObject.class);
		}
		catch (IOException e)
		{
			throw unreachable(request.url(), e);
		}
	}

	private <T> CompletableFuture<T> getAsync(String path, AccountIdentity identity, Type responseType,
		@Nullable String candidateToken)
	{
		CompletableFuture<T> future = new CompletableFuture<>();
		Request request;

		try
		{
			request = requestBuilder(path, identity, candidateToken).get().build();
		}
		catch (ApiException e)
		{
			future.completeExceptionally(e);
			return future;
		}

		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				future.completeExceptionally(unreachable(call.request().url(), e));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (response)
				{
					future.complete(parse(response, identity, responseType, candidateToken == null));
				}
				catch (ApiException e)
				{
					future.completeExceptionally(e);
				}
			}
		});

		return future;
	}

	/** Names the URL and the underlying reason, so a wrong Server URL is obvious. */
	private static ApiException unreachable(HttpUrl url, IOException e)
	{
		log.warn("Irons Grotto request to {} failed", url, e);
		String reason = e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName();
		return new ApiException("Can't reach " + url.scheme() + "://" + url.host() + ":" + url.port() + " (" + reason + ")", e);
	}

	private Request.Builder requestBuilder(String path, AccountIdentity identity) throws ApiException
	{
		return requestBuilder(path, identity, null);
	}

	/** @param candidateToken a token to try instead of the account's saved one */
	private Request.Builder requestBuilder(String path, AccountIdentity identity, @Nullable String candidateToken)
		throws ApiException
	{
		String token = candidateToken != null ? candidateToken : tokens.get(identity);
		if (token.isEmpty())
		{
			throw new ApiException(401, "No plugin token set");
		}

		HttpUrl base = HttpUrl.parse(config.apiBaseUrl());
		if (base == null)
		{
			throw new ApiException(0, "Invalid server URL: " + config.apiBaseUrl());
		}

		// A path may carry a query ("/clan-events?standings=25").
		int query = path.indexOf('?');
		HttpUrl.Builder builder = base.newBuilder().encodedPath(query < 0 ? path : path.substring(0, query));
		if (query >= 0)
		{
			builder.encodedQuery(path.substring(query + 1));
		}
		HttpUrl url = builder.build();

		return new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + token)
			.header("X-Account-Hash", identity.getAccountHash())
			.header("X-Player-Name", identity.getRsn())
			.header("X-Plugin-Version", PLUGIN_VERSION)
			.header("User-Agent", userAgent);
	}

	private <T> T parse(Response response, AccountIdentity identity, Type type) throws ApiException
	{
		return parse(response, identity, type, true);
	}

	/** @param clearOnReject drop the account's saved token if the server says it will never work */
	private <T> T parse(Response response, AccountIdentity identity, Type type, boolean clearOnReject)
		throws ApiException
	{
		JsonObject envelope = readEnvelope(response);

		if (!response.isSuccessful() || envelope == null || !isSuccess(envelope))
		{
			String error = envelope != null && envelope.has("error") && !envelope.get("error").isJsonNull()
				? envelope.get("error").getAsString()
				: response.code() == 404
					? config.apiBaseUrl() + " doesn't support the plugin (404). Check the Server URL setting."
					: "Server returned " + response.code();
			String code = envelope != null && envelope.has("code") && envelope.get("code").isJsonPrimitive()
				? envelope.get("code").getAsString()
				: null;
			ApiException failure = new ApiException(response.isSuccessful() ? 500 : response.code(), error, code);
			if (clearOnReject && failure.isTokenDead())
			{
				tokens.clearRejected(identity, failure.getStatus() == 401
					? "Your token was revoked or isn't recognised. Get a new one."
					: failure.getMessage());
			}
			throw failure;
		}

		JsonElement data = envelope.get("data");
		try
		{
			return gson.fromJson(data, type);
		}
		catch (JsonParseException e)
		{
			throw new ApiException("Unexpected response from the Irons Grotto server.", e);
		}
	}

	private JsonObject readEnvelope(Response response)
	{
		ResponseBody body = response.body();
		if (body == null)
		{
			return null;
		}

		try
		{
			JsonElement element = gson.fromJson(body.string(), JsonElement.class);
			return element != null && element.isJsonObject() ? element.getAsJsonObject() : null;
		}
		catch (IOException | JsonParseException e)
		{
			log.debug("Unparseable response body ({})", response.code(), e);
			return null;
		}
	}

	private static boolean isSuccess(JsonObject envelope)
	{
		return envelope.has("success") && envelope.get("success").getAsBoolean();
	}
}

package com.ironsgrotto.api;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import com.ironsgrotto.IronsGrottoConfig;
import com.ironsgrotto.session.AccountIdentity;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Type;
import java.nio.file.StandardCopyOption;
import java.util.HashMap;
import java.util.Map;
import java.util.function.BiConsumer;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfile;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.util.Filepath;

/**
 * One plugin token per in-game account, kept on this machine only.
 *
 * Per account rather than one setting, because the server binds a token to
 * the first account that uses it: a single token would be sent for every
 * account logged in on this client, including a friend's.
 *
 * Per machine, like any login token, in the plugin's data directory. Up to 1.1.0,
 * the plugin kept tokens in RuneLite's per-account config, which RuneLite syncs between
 * machines: a token pasted on one machine replaced, or wiped, the token on
 * another. A token found there is copied here the first time an account is
 * read, so upgrading needs no new token. The synced copy is left alone, since
 * clients on an older version read it.
 *
 * Tokens are looked up by account hash, not "the current account", because
 * queued events are sent after logout or an account switch,
 * as the account that produced them.
 */
@Slf4j
@Singleton
public class TokenStore
{
	static final String LEGACY_KEY = "token";

	private static final Type TOKEN_MAP = new TypeToken<Map<String, String>>()
	{
	}.getType();

	private final ConfigManager configManager;
	private volatile BiConsumer<AccountIdentity, String> onCleared = (account, reason) -> { };

	/**
	 * Account hash to token. "" is an account whose token was dropped here,
	 * so the old synced copy isn't copied in again.
	 */
	private final Map<String, String> tokens = new HashMap<>();
	@Nullable
	private Filepath file;
	@Nullable
	private Gson gson;
	private boolean loaded;

	@Inject
	TokenStore(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/** Where this machine's tokens live. Until it is set, they are kept in memory. */
	public synchronized void open(Filepath file, Gson gson)
	{
		this.file = file;
		this.gson = gson;
		tokens.clear();
		loaded = false;
	}

	/** Called after the server made us drop an account's token, with why. */
	public void setOnCleared(BiConsumer<AccountIdentity, String> onCleared)
	{
		this.onCleared = onCleared;
	}

	/** The account's token, or "" when it has none. */
	public String get(AccountIdentity account)
	{
		String token = read(account.getAccountHash());
		return token == null ? "" : token.trim();
	}

	public boolean has(AccountIdentity account)
	{
		return !get(account).isEmpty();
	}

	public void set(AccountIdentity account, String token)
	{
		write(account.getAccountHash(), token.trim());
	}

	/** Drops the account's token because the server will never accept it for this account. */
	public void clearRejected(AccountIdentity account, String reason)
	{
		remove(account.getAccountHash());
		onCleared.accept(account, reason);
	}

	@Nullable
	protected synchronized String read(String accountHash)
	{
		load();
		if (!tokens.containsKey(accountHash))
		{
			String synced = readSynced(accountHash);
			if (synced == null || synced.trim().isEmpty())
			{
				return null;
			}
			tokens.put(accountHash, synced.trim());
			save();
		}
		return tokens.get(accountHash);
	}

	protected synchronized void write(String accountHash, String token)
	{
		load();
		tokens.put(accountHash, token);
		save();
	}

	protected synchronized void remove(String accountHash)
	{
		load();
		tokens.put(accountHash, "");
		save();
	}

	/**
	 * The token older versions stored in the account's synced RS profile config, if
	 * any. RuneLite creates an account's RS profile on its first login, so
	 * every account the plugin has seen has one.
	 */
	@Nullable
	protected String readSynced(String accountHash)
	{
		long hash;
		try
		{
			hash = Long.parseLong(accountHash);
		}
		catch (NumberFormatException e)
		{
			return null;
		}

		for (RuneScapeProfile profile : configManager.getRSProfiles())
		{
			if (profile.getAccountHash() == hash && profile.getType() == RuneScapeProfileType.STANDARD)
			{
				return configManager.getConfiguration(IronsGrottoConfig.GROUP, profile.getKey(), LEGACY_KEY);
			}
		}
		return null;
	}

	private void load()
	{
		if (loaded)
		{
			return;
		}
		loaded = true;

		if (file == null || gson == null || !file.exists())
		{
			return;
		}

		try (Reader reader = file.openBufferedReader())
		{
			Map<String, String> stored = gson.fromJson(reader, TOKEN_MAP);
			if (stored != null)
			{
				tokens.putAll(stored);
			}
		}
		catch (IOException | JsonParseException e)
		{
			log.warn("Could not read the Irons Grotto tokens", e);
		}
	}

	/** Written to a temp file and moved into place, like the outbox. */
	private void save()
	{
		if (file == null || gson == null)
		{
			return;
		}

		try
		{
			file.getParent().createDirectories();
			Filepath temp = file.getParent().join(file.getFileName() + ".tmp");

			try (Writer writer = temp.openBufferedWriter())
			{
				gson.toJson(tokens, TOKEN_MAP, writer);
			}

			temp.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
		}
		catch (IOException e)
		{
			log.warn("Could not save the Irons Grotto tokens", e);
		}
	}
}

package com.ironsgrotto.api.model;

import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import lombok.Data;
import lombok.EqualsAndHashCode;

/** {@code GET /api/plugin/clan-events}: the running SOTW/BOTW and the next one. */
@Data
public class ClanEventStatus
{
	@Nullable
	private ActiveEvent active;
	@Nullable
	private EventSummary next;

	@Data
	public static class EventSummary
	{
		private long id;
		/** {@code sotw} or {@code botw}. */
		private String type;
		private String typeLabel;
		private String name;
		private String metricName;
		/** ISO-8601 instants. */
		private String startsAt;
		private String endsAt;
	}

	@Data
	@EqualsAndHashCode(callSuper = true)
	public static class ActiveEvent extends EventSummary
	{
		private int participantCount;
		private List<Standing> standings = new ArrayList<>();
