 * syncs from the side panel.
 *
 * - **Login** — a few ticks in (varbits arrive after the login tick): skills,
 *   diaries, combat achievements, quests and the collection log's counters.
 * - **Logout, and closing the client** — the latest reading again, so the
 *   session's progress lands without waiting for the next login. Game state
 *   is gone by the time the login screen shows, so the reading is the one
 *   taken quietly (in memory, not uploaded) every minute while playing.
 * - **Events that change standing** — a new collection log slot or a pet is
 *   sent straight away, and the panel refreshes when the server has it.
 * - **"Sync collection log"** in the side panel, with the log open — the
 *   whole item list (see {@link CollectionLogSync}).
 * - **Client settings** tracking depends on — on login and whenever the
 *   member changes one, so onboarding sees the fix straight away.
 * - **Game mode** — with the login reading, and the moment it changes (a
 *   hardcore dies, an ironman de-irons).
 *
 * Nothing unchanged is ever re-sent: the uploader skips a category identical
 * to its last upload. Test events from the developer tools never touch
 * progress.
 */
@Singleton
public class ProgressSync
{
	static final int FIRST_READ_TICK = 8;
	/** ~1 minute of 0.6s ticks between in-memory readings. */
	static final int CACHE_EVERY_TICKS = 100;
	/** The last-item varp can land a tick either side of the chat message. */
	private static final int CLOG_ITEM_WAIT_TICKS = 3;

	private final Client client;
	private final AccountSession session;
	private final ProgressCollector collector;
	private final ProgressUploader uploader;
	private final ItemManager itemManager;
	private final SyncExecutor executor;
	private final ClientThread clientThread;
	private final CollectionLogSync collectionLog;

	private AccountIdentity account;
	/** The account whose full log is on its way to the server, if one is. */
	private volatile AccountIdentity awaitingFullLog;
	private int ticksLoggedIn;
	/** The latest cheap reading, for logout; null until the first one. */
	private JsonObject lastReading;

	private String pendingClogItem;
	private int pendingClogTicks;

	@Inject
	ProgressSync(Client client, AccountSession session, ProgressCollector collector, ProgressUploader uploader,
		CollectionLogSync collectionLog, ItemManager itemManager, SyncExecutor executor, ClientThread clientThread)
	{
		this.clientThread = clientThread;
		this.client = client;
		this.session = session;
		this.collector = collector;
		this.uploader = uploader;
		this.itemManager = itemManager;
		this.executor = executor;
		this.collectionLog = collectionLog;
		collectionLog.setOnSnapshot(this::onCollectionLog);
		uploader.setOnSent(this::onProgressSent);
		uploader.setOnDropped(this::onProgressDropped);
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		AccountIdentity current = session.getIdentity();
		if (current == null)
		{
			return;
		}

		if (!current.equals(account))
		{
			account = current;
			ticksLoggedIn = 0;
			lastReading = null;
		}

		ticksLoggedIn++;
		if (ticksLoggedIn == FIRST_READ_TICK)
		{
			lastReading = readCheap();
			submit(current, lastReading);
			uploader.submit(current, "quests", collector.quests());
			uploader.submit(current, "settings", collector.settings());
		}
		else if (ticksLoggedIn > FIRST_READ_TICK && ticksLoggedIn % CACHE_EVERY_TICKS == 0)
		{
			lastReading = readCheap();
		}

		resolvePendingClogItem(current);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN && account != null)
		{
			// Logged out: send what the session ended on.
			submitLastReading();
			executor.execute(uploader::flush);
			account = null;
			lastReading = null;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() == VarbitID.OPTION_COLLECTION_NEW_ITEM)
		{
			submitSettings();
		}
		else if (event.getVarbitId() == VarbitID.IRONMAN)
		{
			submitAccountType();
		}
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		if (event.getPlugin() instanceof LootTrackerPlugin)
		{
			// Posted from whichever thread toggled it; the reading needs the client thread.
			clientThread.invoke(this::submitSettings);
		}
	}

	/** Sends the settings if they changed; only once the login reading has been taken. */
	private void submitSettings()
	{
		AccountIdentity current = session.getIdentity();
		if (current != null && current.equals(account) && ticksLoggedIn >= FIRST_READ_TICK)
		{
			uploader.submit(current, "settings", collector.settings());
		}
	}

	/** Sends a changed game mode; only once the login reading has been taken. */
	private void submitAccountType()
	{
		AccountIdentity current = session.getIdentity();
		String accountType = collector.accountType();
		if (current != null && current.equals(account) && ticksLoggedIn >= FIRST_READ_TICK && accountType != null)
		{
			uploader.submit(current, "accountType", new JsonPrimitive(accountType));
		}
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		if (account != null)
		{
			submitLastReading();
		}
		// RuneLite holds the exit briefly for tasks handed to it.
		event.waitFor(executor.submit(uploader::flush));
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		AccountIdentity current = session.getIdentity();
		if (current == null || event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());

		ChatMessageParser.clueCount(message).ifPresent(clue ->
		{
			JsonObject clues = new JsonObject();
			clues.addProperty(clue.getTier(), clue.getCount());
			uploader.submit(current, "clues", clues);
		});

		ChatMessageParser.collectionLogItem(message).ifPresent(item ->
		{
			pendingClogItem = item;
			pendingClogTicks = 0;
			resolvePendingClogItem(current);
		});

		// A pet always shows in the collection log counters (a new one) or
		// not at all (a duplicate); sending the counters now is what moves
		// the member's standing without waiting for logout.
		ChatMessageParser.petVariant(message).ifPresent(variant -> submitCounters(current));
	}

	/**
	 * A new collection log slot, with its item id: the game's "last obtained"
	 * varp names the item, and is checked against the chat message's name so
	 * a stale value is never sent as the new one.
	 */
	private void resolvePendingClogItem(AccountIdentity current)
	{
		if (pendingClogItem == null)
		{
			return;
		}

		int itemId = client.getVarpValue(VarPlayerID.COLLECTION_OVERVIEW_LAST_ITEM0);
		boolean matches = itemId > 0
			&& pendingClogItem.equalsIgnoreCase(itemManager.getItemComposition(itemId).getMembersName());

		if (!matches && ++pendingClogTicks < CLOG_ITEM_WAIT_TICKS)
		{
			return;
		}

		JsonObject log = collector.collectionLogCounts();
		if (log == null)
		{
			log = new JsonObject();
		}
		if (matches)
		{
			JsonObject item = new JsonObject();
			item.addProperty("id", itemId);
			item.addProperty("name", pendingClogItem);
			item.addProperty("quantity", 1);
			JsonArray items = new JsonArray();
			items.add(item);
			log.add("items", items);
		}
		// Unmatched: the counters still move; the item itself arrives with the
		// next full read of the log.
		if (log.size() > 0)
		{
			uploader.submit(current, "collectionLog", log);
		}
		pendingClogItem = null;
	}

	private void submitCounters(AccountIdentity current)
	{
		JsonObject counts = collector.collectionLogCounts();
		if (counts != null)
		{
			uploader.submit(current, "collectionLog", counts);
		}
	}

	private void submitLastReading()
	{
		if (lastReading != null)
		{
			submit(account, lastReading);
		}
	}

	/** Skills, diaries, CA and clog counters — cheap enough to take every minute. */
	private JsonObject readCheap()
	{
		JsonObject reading = new JsonObject();
		reading.add("skills", collector.skills());
		reading.add("diaries", collector.diaries());
		JsonObject ca = collector.combatAchievements();
		if (ca != null)
		{
			reading.add("combatAchievements", ca);
		}
		JsonObject counts = collector.collectionLogCounts();
		if (counts != null)
		{
			reading.add("collectionLog", counts);
		}
		String accountType = collector.accountType();
		if (accountType != null)
		{
			reading.addProperty("accountType", accountType);
		}
		return reading;
	}

	private void submit(AccountIdentity to, JsonObject reading)
	{
		reading.entrySet().forEach(entry -> uploader.submit(to, entry.getKey(), entry.getValue()));
	}

	private void onCollectionLog(JsonObject snapshot)
	{
		AccountIdentity current = session.getIdentity();
		if (current == null)
		{
			collectionLog.onNotSent();
			return;
		}

		JsonObject counts = collector.collectionLogCounts();
		if (counts != null)
		{
			snapshot.add("obtained", counts.get("obtained"));
			snapshot.add("total", counts.get("total"));
		}
		if (!uploader.submit(current, "collectionLog", snapshot))
		{
			// The same full log already reached the server this session.
			collectionLog.onSent(Collections.emptyList());
			return;
		}
		awaitingFullLog = current;
		executor.execute(uploader::flush);
	}

	private void onProgressSent(JsonObject body, JsonObject result)
	{
		AccountIdentity waiting = awaitingFullLog;
		if (waiting != null && isFullLog(body))
		{
			awaitingFullLog = null;
			// Only mark it synced for the account still logged in: the mark
			// is saved to the logged-in account's profile.
			if (waiting.equals(session.getIdentity()))
			{
				collectionLog.onSent(newCollectionLogItems(result));
			}
		}
	}

	private void onProgressDropped(JsonObject body)
	{
		if (awaitingFullLog != null && isFullLog(body))
		{
			awaitingFullLog = null;
			collectionLog.onNotSent();
		}
	}

	/**
	 * The collection log items the upload added to the member's clan record,
	 * or null if the server didn't say (not a member yet, or an older server).
	 */
	@Nullable
	static List<String> newCollectionLogItems(@Nullable JsonObject result)
	{
		if (result == null || !result.has("newCollectionLogItems") || !result.get("newCollectionLogItems").isJsonArray())
		{
			return null;
		}
		List<String> names = new ArrayList<>();
		result.getAsJsonArray("newCollectionLogItems").forEach(name -> names.add(name.getAsString()));
		return names;
	}

	/** Whether an upload carried a complete collection log, not just its counters or one slot. */
	static boolean isFullLog(JsonObject body)
	{
		JsonObject log = body.has("collectionLog") && body.get("collectionLog").isJsonObject()
			? body.getAsJsonObject("collectionLog") : null;
		return log != null && log.has("complete") && log.get("complete").getAsBoolean();
	}
}

package com.ironsgrotto.progress;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.ironsgrotto.api.ApiException;
import com.ironsgrotto.api.GrottoApiClient;
import com.ironsgrotto.session.AccountIdentity;
import java.time.Clock;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Sends account progress to the server, a category at a time.
 *
 * Progress is state, not history, so there is no queue: the latest reading of
 * each category waits here until it is sent, replacing any older one. A
 * category identical to the last one sent is not sent again. Nothing is kept
 * on disk — a lost reading is simply taken again next login.
 */
@Slf4j
@Singleton
public class ProgressUploader
{
	static final long INITIAL_BACKOFF_MS = 10_000;
	static final long MAX_BACKOFF_MS = 10 * 60_000;

	private final GrottoApiClient api;
	private final Clock clock;

	private final Map<String, JsonObject> pending = new HashMap<>();
	private final Map<String, JsonElement> lastSent = new HashMap<>();
	private AccountIdentity pendingAccount;
	private long nextAttemptAt;
	private long backoffMs = INITIAL_BACKOFF_MS;
	private volatile Consumer<JsonObject> onSynced = result -> { };
	private volatile BiConsumer<JsonObject, JsonObject> onSent = (body, result) -> { };
	private volatile Consumer<JsonObject> onDropped = body -> { };

	@Inject
	ProgressUploader(GrottoApiClient api)
	{
		this(api, Clock.systemUTC());
	}

	ProgressUploader(GrottoApiClient api, Clock clock)
	{
		this.api = api;
		this.clock = clock;
	}

	/** Called with the server's reply (applied categories, points, rank) after each upload. */
	public void setOnSynced(Consumer<JsonObject> onSynced)
	{
		this.onSynced = onSynced;
	}

	/** Called with each request body the server accepted, and the server's reply to it. */
	public void setOnSent(BiConsumer<JsonObject, JsonObject> onSent)
	{
		this.onSent = onSent;
	}

	/** Called with each request body the server refused outright, which is not retried. */
	public void setOnDropped(Consumer<JsonObject> onDropped)
	{
		this.onDropped = onDropped;
	}

	/**
	 * Queues one category's latest reading.
	 *
	 * @return false if it matches what was last sent, so there is nothing to send
	 */
	public synchronized boolean submit(AccountIdentity account, String category, JsonElement value)
	{
		if (!account.equals(pendingAccount))
		{
			// A different account: nothing queued or remembered applies to it.
			pending.clear();
			lastSent.clear();
			pendingAccount = account;
		}

		if (Objects.equals(lastSent.get(category), value))
		{
			return false;
		}

		JsonObject queued = pending.get(category);
		if (queued != null && queued.get(category).isJsonObject() && value.isJsonObject())
		{
			// Merge rather than replace: the collection log's counters and its
			// item list arrive separately and both belong in the next upload.
			JsonObject merged = queued.get(category).getAsJsonObject().deepCopy();
			for (Map.Entry<String, JsonElement> field : value.getAsJsonObject().entrySet())
			{
				merged.add(field.getKey(), field.getValue());
			}
			value = merged;
		}

		JsonObject part = new JsonObject();
		part.add(category, value);
		pending.put(category, part);
		return true;
	}

	/** Sends everything waiting, in one request. Blocking; background threads only. */
	public void flush()
	{
		AccountIdentity account;
		JsonObject body = new JsonObject();

		synchronized (this)
		{
			if (pending.isEmpty() || pendingAccount == null || clock.millis() < nextAttemptAt)
			{
				return;
			}
			account = pendingAccount;
			for (JsonObject part : pending.values())
			{
				for (Map.Entry<String, JsonElement> entry : part.entrySet())
				{
					body.add(entry.getKey(), entry.getValue());
				}
			}
		}

		try
		{
			JsonObject result = api.putProgress(account, body);
			synchronized (this)
			{
				if (account.equals(pendingAccount))
				{
					for (Map.Entry<String, JsonElement> entry : body.entrySet())
					{
						lastSent.put(entry.getKey(), entry.getValue());
						// Only drop it if nothing newer arrived while sending.
						JsonObject queued = pending.get(entry.getKey());
						if (queued != null && Objects.equals(queued.get(entry.getKey()), entry.getValue()))
						{
							pending.remove(entry.getKey());
						}
					}
				}
				backoffMs = INITIAL_BACKOFF_MS;
				nextAttemptAt = 0;
			}
			onSent.accept(body, result);
			onSynced.accept(result);
		}
		catch (ApiException e)
		{
			synchronized (this)
			{
				if (e.isRetryable() || e.isClientBlocked())
				{
					nextAttemptAt = clock.millis() + backoffMs;
					backoffMs = Math.min(backoffMs * 2, MAX_BACKOFF_MS);
				}
				else
				{
					log.warn("Server refused progress ({}), dropping it: {}", body.keySet(), e.getMessage());
					pending.clear();
				}
			}
			if (!e.isRetryable() && !e.isClientBlocked())
			{
				onDropped.accept(body);
			}
		}
	}

	public synchronized boolean hasPending()
	{
		return !pending.isEmpty();
	}
}

package com.ironsgrotto.session;

import lombok.Value;

/**
 * The in-game account a request speaks for. Captured when the data is
 * produced, so queued work is always sent as the account that generated it,
 * even if the player has since switched accounts.
 */
@Value
public class AccountIdentity
{
	/** RuneLite's account hash, as decimal text so it survives JSON exactly. */
	String accountHash;
	String rsn;
}

package com.ironsgrotto.session;

import java.util.EnumSet;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldType;

/**
 * Tracks which account is logged in, and whether its activity should count.
 *
 * The local player's name is not available on the tick the game reports
 * LOGGED_IN, so {@link #poll()} is called every game tick until it is. The
 * plugin calls {@link #clear()} on logout and world hops, so a hop onto an
 * excluded world stops tracking.
 */
@Slf4j
@Singleton
public class AccountSession
{
	/**
	 * Worlds whose progress is not the member's real account: temporary game
	 * modes, practice modes and worlds that reset.
	 */
	private static final Set<WorldType> EXCLUDED_WORLD_TYPES = EnumSet.of(
		WorldType.SEASONAL,
		WorldType.DEADMAN,
		WorldType.BETA_WORLD,
		WorldType.FRESH_START_WORLD,
		WorldType.PVP_ARENA,
		WorldType.QUEST_SPEEDRUNNING,
		WorldType.TOURNAMENT_WORLD,
		WorldType.NOSAVE_MODE
	);

	private final Client client;

	@Nullable
	private volatile AccountIdentity identity;

	@Inject
	AccountSession(Client client)
	{
		this.client = client;
	}

	/**
	 * Captures the account once the game can tell us who it is.
	 *
	 * @return true when the identity changed on this call
	 */
	public boolean poll()
	{
		if (identity != null || client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}

		Player player = client.getLocalPlayer();
		long hash = client.getAccountHash();

		if (player == null || player.getName() == null || hash == -1)
		{
			return false;
		}

		if (!isTrackedWorld())
		{
			return false;
		}

		identity = new AccountIdentity(Long.toString(hash), sanitiseName(player.getName()));
		log.debug("Irons Grotto session started for {}", identity.getRsn());
		return true;
	}

	/** @return true when there was an identity to clear */
	public boolean clear()
	{
		boolean had = identity != null;
		identity = null;
		return had;
	}

	/** The logged-in account, or null when logged out or on an excluded world. */
	@Nullable
	public AccountIdentity getIdentity()
	{
		return identity;
	}

	public boolean isTrackedWorld()
	{
		for (WorldType type : client.getWorldType())
		{
			if (EXCLUDED_WORLD_TYPES.contains(type))
			{
				return false;
			}
		}
		return true;
	}

	/** The game uses non-breaking spaces in names; the clan roster does not. */
	static String sanitiseName(String name)
	{
		return name.replace(' ', ' ').trim();
	}
}

package com.ironsgrotto.tracker;

import com.google.gson.JsonObject;
import com.ironsgrotto.ledger.LedgerEventType;
import com.ironsgrotto.ledger.LedgerRecorder;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Kill counts, new collection log slots and pets, from the game's own chat
 * messages.
 *
 * The collection log message needs the in-game setting "Collection log — new
 * addition notification" set to chat (or both).
 */
@Singleton
public class ChatEventTracker
{
	private final LedgerRecorder recorder;

	@Inject
	ChatEventTracker(LedgerRecorder recorder)
	{
		this.recorder = recorder;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());

		ChatMessageParser.killCount(message).ifPresent(kill ->
		{
			JsonObject payload = new JsonObject();
			payload.addProperty("boss", kill.getBoss());
			payload.addProperty("kc", kill.getKc());
			recorder.record(LedgerEventType.BOSS_KC, payload);
		});

		ChatMessageParser.collectionLogItem(message).ifPresent(item ->
		{
			JsonObject payload = new JsonObject();
			payload.addProperty("itemName", item);
			recorder.record(LedgerEventType.COLLECTION_LOG_ITEM, payload);
		});

		ChatMessageParser.petVariant(message).ifPresent(variant ->
		{
			JsonObject payload = new JsonObject();
			payload.addProperty("variant", variant);
			payload.addProperty("message", message);
			recorder.record(LedgerEventType.PET, payload);
		});
	}
}

package com.ironsgrotto.tracker;

import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;

/**
 * Reads the game messages the ledger cares about. Pure, so every pattern is
 * unit tested against the game's real wording.
 *
 * Messages must already have their colour tags removed.
 */
public final class ChatMessageParser
{
	/*
	 * "Your Vorkath kill count is: 123."
	 * "Your completed Chambers of Xeric count is: 5."
	 * "Your Barrows chest count is: 1,234."
	 * "Your subdued Wintertodt count is: 10."
	 * "Your Gauntlet completion count is: 3."
	 */
	private static final Pattern KILL_COUNT = Pattern.compile(
		"^Your (?:completed |subdued )?(.+?)(?: total)?(?: kill| chest| completion| harvest| success)? count is: ([\\d,]+)\\.?$");

	private static final Pattern COLLECTION_LOG = Pattern.compile(
		"^New item added to your collection log: (.+?)\\.?$");

	/* "You have completed 12 hard Treasure Trails." */
	private static final Pattern CLUE_COUNT = Pattern.compile(
		"^You have completed ([\\d,]+) (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.?$", Pattern.CASE_INSENSITIVE);

	private static final String PET_FOLLOWER = "You have a funny feeling like you're being followed";
	private static final String PET_BACKPACK = "You feel something weird sneaking into your backpack";
	private static final String PET_DUPLICATE = "You have a funny feeling like you would have been followed";

	private ChatMessageParser()
	{
	}

	@Value
	public static class KillCount
	{
		String boss;
		int kc;
	}

	public static Optional<KillCount> killCount(String message)
	{
		// Agility courses use the same wording for laps; they are not kills.
		if (message.contains(" lap count is"))
		{
			return Optional.empty();
		}

		Matcher matcher = KILL_COUNT.matcher(message.trim());
		if (!matcher.matches())
		{
			return Optional.empty();
		}

		try
		{
			int kc = Integer.parseInt(matcher.group(2).replace(",", ""));
			return kc > 0 ? Optional.of(new KillCount(matcher.group(1).trim(), kc)) : Optional.empty();
		}
		catch (NumberFormatException e)
		{
			return Optional.empty();
		}
	}

	public static Optional<String> collectionLogItem(String message)
	{
		Matcher matcher = COLLECTION_LOG.matcher(message.trim());
		return matcher.matches() ? Optional.of(matcher.group(1).trim()) : Optional.empty();
	}

	@Value
	public static class ClueCount
	{
		/** Beginner, Easy, Medium, Hard, Elite or Master — the server's tier names. */
		String tier;
		int count;
	}

	public static Optional<ClueCount> clueCount(String message)
	{
		Matcher matcher = CLUE_COUNT.matcher(message.trim());
		if (!matcher.matches())
		{
			return Optional.empty();
		}
		String tier = matcher.group(2).toLowerCase();
		try
		{
			return Optional.of(new ClueCount(
				Character.toUpperCase(tier.charAt(0)) + tier.substring(1),
				Integer.parseInt(matcher.group(1).replace(",", ""))));
		}
		catch (NumberFormatException e)
		{
			return Optional.empty();
		}
	}

	/** @return follower, backpack or duplicate — the server's pet variants */
	public static Optional<String> petVariant(String message)
	{
		if (message.startsWith(PET_DUPLICATE))
		{
			return Optional.of("duplicate");
		}
		if (message.startsWith(PET_FOLLOWER))
		{
			return Optional.of("follower");
		}
		if (message.startsWith(PET_BACKPACK))
		{
			return Optional.of("backpack");
		}
		return Optional.empty();
	}
}

package com.ironsgrotto.tracker;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.ironsgrotto.ledger.LedgerEventType;
import com.ironsgrotto.ledger.LedgerRecorder;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.util.Text;
import net.runelite.http.api.loottracker.LootRecordType;

/**
 * Every drop, as RuneLite's loot events report it.
 *
 * NPC loot is {@link ServerNpcLoot}: the game itself reports every NPC drop
 * through its loot-tracker script (7192), and RuneLite's core loot manager
 * passes it on whether or not the Loot Tracker plugin is on. It covers loot
 * that never touches the ground (the Maggot King) as well as ordinary drops.
 * RuneLite's own Loot Tracker uses only this for NPCs; the older ground-item
 * event ({@code NpcLootReceived}) is not used here, or every ground drop would
 * be recorded twice.
 *
 * PvP kills come from the core {@link PlayerLootReceived}. Everything that is
 * not an NPC or a player — raids, clues, Barrows, Wintertodt and other
 * minigames, pickpockets — is only reported by the Loot Tracker plugin, so it
 * must be enabled for those. Its NPC and PLAYER events are skipped, because
 * the core events above already cover them.
 */
@Singleton
public class LootEventTracker
{
	/**
	 * Sailing salvage, which the Loot Tracker reports as an event named
	 * "<Tier> salvage" every time some is sorted. Thousands a session and no
	 * clan event is decided by it, so it is never queued. The server drops it
	 * too, for plugins older than this check.
	 */
	private static final Pattern SALVAGE = Pattern.compile("^\\S+ salvage$", Pattern.CASE_INSENSITIVE);

	/** The game's message for a successful pickpocket, as the Loot Tracker matches it. */
	private static final Pattern PICKPOCKET = Pattern.compile("You pick (the )?(?<target>.+)'s? pocket.*");

	private final LedgerRecorder recorder;
	private final ItemManager itemManager;
	private final Client client;

	/**
	 * The tick of the last pickpocket. The game reports pickpocket loot through
	 * the same script as a kill, so on that tick the server's NPC loot is the
	 * pickpocket, which the Loot Tracker records as PICKPOCKET loot instead.
	 */
	private int pickpocketTick = -1;

	@Inject
	LootEventTracker(LedgerRecorder recorder, ItemManager itemManager, Client client)
	{
		this.recorder = recorder;
		this.itemManager = itemManager;
		this.client = client;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if ((event.getType() == ChatMessageType.SPAM || event.getType() == ChatMessageType.GAMEMESSAGE)
			&& isPickpocket(event.getMessage()))
		{
			pickpocketTick = client.getTickCount();
		}
	}

	/** Every NPC's loot, as the game reports it. */
	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot event)
	{
		NPCComposition npc = event.getComposition();
		if (npc == null || npc.getName() == null || client.getTickCount() == pickpocketTick)
		{
			return;
		}
		record(Text.removeTags(npc.getName()), LootRecordType.NPC, npc.getCombatLevel(), event.getItems());
	}

	static boolean isPickpocket(String message)
	{
		return message != null && PICKPOCKET.matcher(Text.removeTags(message)).matches();
	}

	@Subscribe
	public void onPlayerLootReceived(PlayerLootReceived event)
	{
		Player player = event.getPlayer();
		record(player.getName(), LootRecordType.PLAYER, player.getCombatLevel(), event.getItems());
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (event.getType() == LootRecordType.NPC || event.getType() == LootRecordType.PLAYER
			|| isIgnored(event.getType(), event.getName()))
		{
			return;
		}
		record(event.getName(), event.getType(), event.getCombatLevel(), event.getItems());
	}

	/** Loot that is never recorded: sailing salvage. */
	static boolean isIgnored(LootRecordType type, String source)
	{
		return type == LootRecordType.EVENT && source != null && SALVAGE.matcher(source).matches();
	}

	private void record(String source, LootRecordType type, int combatLevel, Collection<ItemStack> stacks)
	{
		if (source == null || stacks == null || stacks.isEmpty())
		{
			return;
		}

		// Stacks of the same item arrive separately (e.g. two piles of bones).
		Map<Integer, Integer> quantities = new LinkedHashMap<>();
		for (ItemStack stack : stacks)
		{
			int id = itemManager.canonicalize(stack.getId());
			quantities.merge(id, stack.getQuantity(), Integer::sum);
		}

		JsonArray items = new JsonArray();
		long total = 0;
		for (Map.Entry<Integer, Integer> entry : quantities.entrySet())
		{
			int id = entry.getKey();
			int quantity = entry.getValue();
			long price = itemManager.getItemPrice(id);

			JsonObject item = new JsonObject();
			item.addProperty("id", id);
			// The members name: on a free world `getName()` is the F2P display
			// name, e.g. "Skeletal visage (Members)".
			item.addProperty("name", itemManager.getItemComposition(id).getMembersName());
			item.addProperty("quantity", quantity);
			item.addProperty("price", price);
			items.add(item);
			total += price * quantity;
		}

		JsonObject payload = new JsonObject();
		payload.addProperty("source", source);
		payload.addProperty("sourceType", type.name());
		if (combatLevel > 0)
		{
			payload.addProperty("combatLevel", combatLevel);
		}
		payload.add("items", items);
		payload.addProperty("totalValue", total);

		recorder.record(LedgerEventType.LOOT, payload);
	}
}

package com.ironsgrotto.ui;

import com.ironsgrotto.IronsGrottoConfig;
import com.ironsgrotto.IronsGrottoPlugin;
import com.ironsgrotto.api.model.ClanEventStatus;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.text.NumberFormat;
import java.util.List;
import javax.annotation.Nullable;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The running SOTW/BOTW on the game screen, for members who would rather not
 * keep the side panel open.
 *
 * RuneLite does the moving and sizing: hold Alt to drag it anywhere, drag an
 * edge to resize, right-click with Alt to reset; position and size are saved.
 * Its height decides how many standings fit, so dragging it taller shows more.
 */
public class ClanEventOverlay extends OverlayPanel
{
	/** Rows shown before the member has resized it. */
	static final int DEFAULT_ROWS = 3;
	private static final Color TITLE = new Color(255, 152, 31);
	private static final Color LEADER = new Color(76, 175, 120);
	private static final Color GAINED = Color.YELLOW;
	private static final NumberFormat NUMBERS = NumberFormat.getIntegerInstance();

	private final IronsGrottoConfig config;
	@Nullable
	private volatile ClanEventStatus status;

	@Inject
	ClanEventOverlay(IronsGrottoPlugin plugin, IronsGrottoConfig config)
	{
		super(plugin);
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setResizable(true);
		setResettable(true);
		setMinimumSize(110);
	}

	/** The latest standings; called from any thread. */
	public void setStatus(@Nullable ClanEventStatus status)
	{
		this.status = status;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		ClanEventStatus current = status;
		if (!config.showEventOverlay() || current == null)
		{
			return null;
		}

		panelComponent.setBackgroundColor(config.overlayBackground());
		ClanEventStatus.ActiveEvent active = current.getActive();
		ClanEventStatus.EventSummary next = current.getNext();

		if (active == null)
		{
			if (next == null)
			{
				return null;
			}
			// Nothing running: say what's coming and when.
			title("Next " + GrottoPanel.shortType(next.getType()) + ": " + next.getMetricName());
			subtitle(GrottoPanel.timeLeft("Starts", next.getStartsAt()));
			return super.render(graphics);
		}

		title(GrottoPanel.shortType(active.getType()) + ": " + active.getMetricName());
		subtitle(GrottoPanel.timeLeft("Ends", active.getEndsAt()));

		List<ClanEventStatus.Standing> standings = active.getStandings();
		if (active.isStandingsUnavailable())
		{
			subtitle("Standings unavailable");
		}
		else if (standings.isEmpty())
		{
			subtitle("No gains yet");
		}
		else
		{
			Dimension size = getPreferredSize();
			int lineHeight = graphics.getFontMetrics().getHeight() + 1;
			int rows = rowsFor(size == null ? 0 : size.height, lineHeight, standings.size());
			for (ClanEventStatus.Standing standing : standings.subList(0, rows))
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(standing.getPosition() + ". " + standing.getPlayerName())
					.leftColor(standing.getPosition() == 1 ? LEADER : Color.WHITE)
					.right(NUMBERS.format(standing.getGained()))
					.rightColor(GAINED)
					.build());
			}
		}

		return super.render(graphics);
	}

	private void title(String text)
	{
		panelComponent.getChildren().add(TitleComponent.builder().text(text).color(TITLE).build());
	}

	private void subtitle(String text)
	{
		if (!text.isEmpty())
		{
			panelComponent.getChildren().add(TitleComponent.builder().text(text).color(Color.LIGHT_GRAY).build());
		}
	}

	/**
	 * How many standings fit in a box of this height: what is left after the
	 * border and the two title lines, one line per row, at least one and no
	 * more than there are. An overlay never resized (height 0) shows the
	 * default.
	 */
	static int rowsFor(int height, int lineHeight, int available)
	{
		if (available <= 0)
		{
			return 0;
		}
		if (height <= 0 || lineHeight <= 0)
		{
			return Math.min(DEFAULT_ROWS, available);
		}
		int border = ComponentConstants.STANDARD_BORDER * 2;
		int rows = (height - border - 2 * lineHeight) / lineHeight;
		return Math.max(1, Math.min(available, rows));
	}
}

package com.ironsgrotto.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.annotation.Nullable;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * One block of the side panel: a header that folds the block away when
 * clicked, and a body the panel fills. Whether it is folded is remembered per
 * block (see {@link Store}), so a member's layout survives a restart.
 *
 * Swing thread only, like the rest of the panel.
 */
public class CollapsibleSection extends JPanel
{
	/** Remembers which blocks are folded. */
	public interface Store
	{
		boolean isCollapsed(String id);

		void setCollapsed(String id, boolean collapsed);
	}

	/** Caret colour; brighter while the header is hovered. */
	private static final Color CARET = ColorScheme.LIGHT_GRAY_COLOR;
	private static final Color CARET_HOVER = Color.WHITE;

	private final String id;
	private final Store store;
	private final JLabel title = new JLabel();
	private final JLabel aside = new JLabel();
	private final JLabel chevron = new JLabel();
	private final JPanel body = new JPanel();
	/** Held open whatever the member chose, while it asks them to act (the token prompt). */
	private boolean pinnedOpen;
	private final Caret caret = new Caret();

	CollapsibleSection(String id, Store store)
	{
		this.id = id;
		this.store = store;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setVisible(false);

		// Sized from its contents on every layout: fixing it once, before it has
		// a title, gave it no height, and a folded block then had nothing to
		// click to open it again.
		JPanel header = new JPanel(new BorderLayout(4, 0))
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(PluginPanel.PANEL_WIDTH, getPreferredSize().height);
			}
		};
		header.setOpaque(false);
		header.setToolTipText("Click to show or hide");
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		header.add(title, BorderLayout.CENTER);

		JPanel right = new JPanel();
		right.setLayout(new BoxLayout(right, BoxLayout.X_AXIS));
		right.setOpaque(false);
		aside.setFont(FontManager.getRunescapeSmallFont());
		aside.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		chevron.setIcon(caret);
		right.add(aside);
		right.add(Box.createHorizontalStrut(6));
		right.add(chevron);
		header.add(right, BorderLayout.EAST);

		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (!pinnedOpen)
				{
					store.setCollapsed(id, !store.isCollapsed(id));
					refreshFolding();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				setHovered(true);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				setHovered(false);
			}
		});

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setOpaque(false);
		body.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.setBorder(new EmptyBorder(4, 0, 0, 0));

		add(header);
		add(body);
		refreshFolding();
	}

	/** Empties the block for a fresh render: no note, no pin. */
	void clear(String titleText)
	{
		body.removeAll();
		title.setText(titleText);
		aside.setText("");
		pinnedOpen = false;
		refreshFolding();
	}

	void setTitle(String text)
	{
		title.setText(text);
	}

	/** A short note right of the title ("last 24h"); null for none. */
	void setAside(@Nullable String text)
	{
		aside.setText(text == null ? "" : text);
	}

	/** Keeps the block open (and unfoldable) while it needs the member. */
	void setPinnedOpen(boolean pinned)
	{
		pinnedOpen = pinned;
		refreshFolding();
	}

	JPanel body()
	{
		return body;
	}

	private void refreshFolding()
	{
		boolean collapsed = !pinnedOpen && store.isCollapsed(id);
		body.setVisible(!collapsed);
		caret.open = !collapsed;
		chevron.setVisible(!pinnedOpen);
		revalidate();
		repaint();
	}

	private void setHovered(boolean hovered)
	{
		if (pinnedOpen)
		{
			return;
		}
		caret.color = hovered ? CARET_HOVER : CARET;
		title.setForeground(hovered ? ColorScheme.BRAND_ORANGE : Color.WHITE);
		chevron.repaint();
	}

	/**
	 * A small filled triangle, pointing down when open and right when folded.
	 * Drawn rather than typed: the RuneScape font has no arrow glyphs.
	 */
	private static final class Caret implements Icon
	{
		private static final int SIZE = 9;
		private boolean open = true;
		private Color color = CARET;

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(color);
			Polygon triangle = open
				? new Polygon(new int[]{x, x + SIZE, x + SIZE / 2}, new int[]{y + 2, y + 2, y + SIZE - 1}, 3)
				: new Polygon(new int[]{x + 2, x + SIZE - 1, x + 2}, new int[]{y, y + SIZE / 2, y + SIZE}, 3);
			g2.fill(triangle);
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return SIZE;
		}

		@Override
		public int getIconHeight()
		{
			return SIZE;
		}
	}
}

