package com.ironsgrotto.api;

import com.google.gson.Gson;
import com.ironsgrotto.IronsGrottoConfig;
import com.ironsgrotto.api.model.MeResponse;
import com.ironsgrotto.api.model.Registration;
import com.ironsgrotto.session.AccountIdentity;
import java.util.concurrent.ExecutionException;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class GrottoApiClientTest
{
	private static final AccountIdentity ACCOUNT = new AccountIdentity("-4611686018427387904", "Iron Dude");
	private static final AccountIdentity ALT = new AccountIdentity("42", "Alt Dude");

	private MockWebServer server;
	private GrottoApiClient client;
	private MemoryTokenStore tokens;

	@Before
	public void setUp() throws Exception
	{
		server = new MockWebServer();
		server.start();
		String baseUrl = server.url("/").toString();

		tokens = new MemoryTokenStore();
		tokens.set(ACCOUNT, "igp_test");

		IronsGrottoConfig config = new IronsGrottoConfig()
		{
			@Override
			public String apiBaseUrl()
			{
				return baseUrl;
			}
		};

		client = new GrottoApiClient(new OkHttpClient(), new Gson(), config, tokens, "test-agent");
	}

	@After
	public void tearDown() throws Exception
	{
		server.shutdown();
	}

	@Test
	public void sendsTokenAndAccountHeaders() throws Exception
	{
		server.enqueue(new MockResponse().setBody("{\"success\":true,\"data\":{\"rsn\":\"Iron Dude\",\"member\":null,\"joinUrl\":\"https://x/join\",\"policy\":{\"panelRefreshSeconds\":120}}}"));

		MeResponse me = client.getMe(ACCOUNT).get();

		RecordedRequest request = server.takeRequest();
		assertEquals("/api/plugin/v1/me", request.getPath());
		assertEquals(GrottoApiClient.PLUGIN_VERSION, request.getHeader("X-Plugin-Version"));
		assertEquals("Bearer igp_test", request.getHeader("Authorization"));
		assertEquals(ACCOUNT.getAccountHash(), request.getHeader("X-Account-Hash"));
		assertEquals("Iron Dude", request.getHeader("X-Player-Name"));
		assertNull(me.getMember());
		assertEquals("https://x/join", me.getJoinUrl());
		assertEquals(120, me.getPolicy().getPanelRefreshSeconds());
	}

	@Test
	public void surfacesTheServersErrorMessage() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(403).setBody("{\"success\":false,\"error\":\"Not yours\"}"));

		try
		{
			client.getMe(ACCOUNT).get();
			fail("expected an error");
		}
		catch (ExecutionException e)
		{
			ApiException cause = (ApiException) e.getCause();
			assertEquals(403, cause.getStatus());
			assertEquals("Not yours", cause.getMessage());
			assertTrue(!cause.isRetryable());
		}
	}

	@Test
	public void refusesToSendWithoutAToken() throws Exception
	{
		tokens.set(ACCOUNT, " ");

		try
		{
			client.getMe(ACCOUNT).get();
			fail("expected an error");
		}
		catch (ExecutionException e)
		{
			assertTrue(((ApiException) e.getCause()).isUnauthorized());
			assertEquals(0, server.getRequestCount());
		}
	}

	@Test
	public void blockingPostTreatsServerErrorsAsRetryable()
	{
		server.enqueue(new MockResponse().setResponseCode(502).setBody("Bad gateway"));

		try
		{
			client.postBlocking(GrottoApiClient.API_PREFIX + "/events", ACCOUNT, new Object(), Object.class);
			fail("expected an error");
		}
		catch (ApiException e)
		{
			assertEquals(502, e.getStatus());
			assertTrue(e.isRetryable());
		}
	}

	@Test
	public void sendsEachAccountItsOwnToken() throws Exception
	{
		tokens.set(ALT, "igp_alt");
		server.enqueue(new MockResponse().setBody("{\"success\":true,\"data\":{}}"));

		client.getMe(ALT).get();

		assertEquals("Bearer igp_alt", server.takeRequest().getHeader("Authorization"));
	}

	@Test
	public void neverSendsAnotherAccountsToken()
	{
		try
		{
			client.getMe(ALT).get();
			fail("expected an error");
		}
		catch (InterruptedException | ExecutionException e)
		{
			assertTrue(((ApiException) e.getCause()).isUnauthorized());
			assertEquals(0, server.getRequestCount());
		}
	}

	@Test
	public void dropsTheTokenWhenTheServerSaysItIsForAnotherAccount()
	{
		AccountIdentity[] cleared = new AccountIdentity[1];
		tokens.setOnCleared((account, reason) -> cleared[0] = account);
		server.enqueue(new MockResponse().setResponseCode(403)
			.setBody("{\"success\":false,\"error\":\"This token is for a different account.\",\"code\":\"token_account_mismatch\"}"));

		try
		{
			client.postBlocking(GrottoApiClient.API_PREFIX + "/events", ACCOUNT, new Object(), Object.class);
			fail("expected an error");
		}
		catch (ApiException e)
		{
			assertTrue(e.isTokenRejectedForAccount());
			assertTrue(e.isClientBlocked());
		}

		assertEquals("", tokens.get(ACCOUNT));
		assertEquals(ACCOUNT, cleared[0]);
	}

	@Test
	public void keepsTheTokenOnOtherRefusals()
	{
		server.enqueue(new MockResponse().setResponseCode(403).setBody("{\"success\":false,\"error\":\"Nope\"}"));

		try
		{
			client.postBlocking(GrottoApiClient.API_PREFIX + "/events", ACCOUNT, new Object(), Object.class);
			fail("expected an error");
		}
		catch (ApiException e)
		{
			assertEquals(403, e.getStatus());
		}

		assertEquals("igp_test", tokens.get(ACCOUNT));
	}

	@Test
	public void checksAPastedTokenWithoutUsingTheSavedOne() throws Exception
	{
		server.enqueue(new MockResponse().setBody("{\"success\":true,\"data\":{}}"));

		client.checkToken(ACCOUNT, " igp_pasted ").get();

		assertEquals("Bearer igp_pasted", server.takeRequest().getHeader("Authorization"));
		assertEquals("igp_test", tokens.get(ACCOUNT));
	}

	@Test
	public void aRefusedCandidateNeverClearsTheSavedToken()
	{
		server.enqueue(new MockResponse().setResponseCode(403)
			.setBody("{\"success\":false,\"error\":\"This token is for a different account.\",\"code\":\"token_account_mismatch\"}"));

		try
		{
			client.checkToken(ACCOUNT, "igp_other").get();
			fail("expected an error");
		}
		catch (InterruptedException | ExecutionException e)
		{
			assertTrue(((ApiException) e.getCause()).isTokenRejectedForAccount());
		}

		assertEquals("igp_test", tokens.get(ACCOUNT));
	}

	@Test
	public void asksWhetherANameIsRegisteredWithoutAnyCredentials() throws Exception
	{
		tokens.set(ACCOUNT, "igp_secret");
		server.enqueue(new MockResponse().setBody("{\"success\":true,\"data\":{\"registered\":true}}"));

		assertTrue(client.checkRegistration("Iron Dude").get().isRegistered());

		RecordedRequest request = server.takeRequest();
		assertEquals("/api/plugin/v1/public/registration?rsn=Iron%20Dude", request.getPath());
		assertNull(request.getHeader("Authorization"));
		assertNull(request.getHeader("X-Account-Hash"));
		assertEquals(GrottoApiClient.PLUGIN_VERSION, request.getHeader("X-Plugin-Version"));
	}

	@Test
	public void readsAnUnregisteredName() throws Exception
	{
		server.enqueue(new MockResponse().setBody("{\"success\":true,\"data\":{\"registered\":false}}"));

		Registration registration = client.checkRegistration("Nobody Here").get();
		assertFalse(registration.isRegistered());
		// A server without the field always made the token on /join.
		assertTrue(registration.sendsToJoin());
	}

	@Test
	public void sendsANewAccountToTheTokenPageWhileJoiningCantMakeOne() throws Exception
	{
		server.enqueue(new MockResponse().setBody(
			"{\"success\":true,\"data\":{\"registered\":false,\"pluginOnboarding\":false}}"));

		assertFalse(client.checkRegistration("Nobody Here").get().sendsToJoin());
	}

	@Test
	public void sendsARegisteredAccountToTheTokenPage() throws Exception
	{
		server.enqueue(new MockResponse().setBody(
			"{\"success\":true,\"data\":{\"registered\":true,\"pluginOnboarding\":true}}"));

		assertFalse(client.checkRegistration("Iron Dude").get().sendsToJoin());
	}

	@Test
	public void dropsATokenTheServerNoLongerRecognises()
	{
		String[] reason = new String[1];
		tokens.setOnCleared((account, why) -> reason[0] = why);
		server.enqueue(new MockResponse().setResponseCode(401)
			.setBody("{\"success\":false,\"error\":\"Invalid or revoked plugin token\"}"));

		try
		{
			client.postBlocking(GrottoApiClient.API_PREFIX + "/events", ACCOUNT, new Object(), Object.class);
			fail("expected an error");
		}
		catch (ApiException e)
		{
			assertTrue(e.isTokenDead());
			assertTrue(e.isClientBlocked());
		}

		assertEquals("", tokens.get(ACCOUNT));
		assertTrue(reason[0].contains("revoked"));
	}
}

package com.ironsgrotto.api;

import java.util.HashMap;
import java.util.Map;

/** A {@link TokenStore} in memory, keyed by account hash, for tests. */
public class MemoryTokenStore extends TokenStore
{
	final Map<String, String> tokens = new HashMap<>();

	public MemoryTokenStore()
	{
		super(null);
	}

	@Override
	protected String read(String accountHash)
	{
		return tokens.get(accountHash);
	}

	@Override
	protected void write(String accountHash, String token)
	{
		tokens.put(accountHash, token);
	}

	@Override
	protected void remove(String accountHash)
	{
		tokens.remove(accountHash);
	}
}

package com.ironsgrotto.api;

import com.google.gson.Gson;
import com.ironsgrotto.session.AccountIdentity;
import java.nio.file.Files;
import java.util.HashMap;
import java.util.Map;
import net.runelite.client.util.Filepath;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TokenStoreTest
{
	private static final AccountIdentity MAIN = new AccountIdentity("123", "Iron Dude");
	private static final AccountIdentity ALT = new AccountIdentity("456", "Iron Alt");

	/** What 1.1.0 left in the synced RS profile config, by account hash. */
	private final Map<String, String> synced = new HashMap<>();
	private Filepath file;

	@Before
	public void setUp() throws Exception
	{
		file = Filepath.Unchecked.getRooted(Files.createTempDirectory("tokens")).join("tokens.json");
	}

	private TokenStore store()
	{
		TokenStore store = new TokenStore(null)
		{
			@Override
			protected String readSynced(String accountHash)
			{
				return synced.get(accountHash);
			}
		};
		store.open(file, new Gson());
		return store;
	}

	@Test
	public void keepsTokensPerAccountAcrossRestarts()
	{
		TokenStore store = store();
		store.set(MAIN, " igp_main ");
		store.set(ALT, "igp_alt");

		TokenStore restarted = store();
		assertEquals("igp_main", restarted.get(MAIN));
		assertEquals("igp_alt", restarted.get(ALT));
	}

	@Test
	public void copiesTheSyncedTokenOnce()
	{
		synced.put(MAIN.getAccountHash(), "igp_synced");
		assertEquals("igp_synced", store().get(MAIN));

		// Another machine pasting a new token no longer changes this one.
		synced.put(MAIN.getAccountHash(), "igp_other_machine");
		assertEquals("igp_synced", store().get(MAIN));
	}

	@Test
	public void aTokenSetHereWinsOverTheSyncedOne()
	{
		synced.put(MAIN.getAccountHash(), "igp_synced");
		TokenStore store = store();
		store.set(MAIN, "igp_local");

		assertEquals("igp_local", store().get(MAIN));
	}

	@Test
	public void aRejectedTokenIsNotCopiedBackFromSync()
	{
		synced.put(MAIN.getAccountHash(), "igp_synced");
		TokenStore store = store();
		assertTrue(store.has(MAIN));

		store.clearRejected(MAIN, "revoked");

		assertFalse(store.has(MAIN));
		assertFalse(store().has(MAIN));
	}

	@Test
	public void anAccountWithNoTokenHasNone()
	{
		assertEquals("", store().get(MAIN));
		assertFalse(store().has(MAIN));
	}
}

package com.ironsgrotto.ledger;

import com.google.gson.JsonObject;
import com.ironsgrotto.outbox.OutboxEntry;
import com.ironsgrotto.session.AccountIdentity;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

public class KillLootLinkerTest
{
	private static final AccountIdentity ACCOUNT = new AccountIdentity("1", "Iron Dude");

	private long now = 1_000_000;
	private final KillLootLinker linker = new KillLootLinker(new Clock()
	{
		@Override
		public ZoneId getZone()
		{
			return ZoneOffset.UTC;
		}

		@Override
		public Clock withZone(ZoneId zone)
		{
			return this;
		}

		@Override
		public Instant instant()
		{
			return Instant.ofEpochMilli(now);
		}
	});

	private static OutboxEntry kc(String boss, int kc)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("boss", boss);
		payload.addProperty("kc", kc);
		return OutboxEntry.create(LedgerEventType.BOSS_KC, payload, ACCOUNT, Instant.EPOCH);
	}

	private static OutboxEntry loot(String source, long value)
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("source", source);
		payload.addProperty("totalValue", value);
		return OutboxEntry.create(LedgerEventType.LOOT, payload, ACCOUNT, Instant.EPOCH);
	}

	@Test
	public void lootAfterAKillCarriesTheKill()
	{
		OutboxEntry kill = kc("Vorkath", 101);
		OutboxEntry drop = loot("Vorkath", 4_000_000);

		linker.link(kill);
		now += 600;
		linker.link(drop);

		assertEquals(101, drop.getPayload().get("kc").getAsInt());
		assertEquals("Vorkath", drop.getPayload().get("kcBoss").getAsString());
		assertEquals(kill.getId(), drop.getPayload().get("kcEventId").getAsString());
	}

	@Test
	public void aRaidChestOpenedLaterStillLinksAcrossModes()
	{
		OutboxEntry kill = kc("Theatre of Blood: Hard Mode", 12);
		OutboxEntry chest = loot("Theatre of Blood", 1_500_000);

		linker.link(kill);
		now += 5 * 60_000;
		linker.link(chest);

		assertEquals("Theatre of Blood: Hard Mode", chest.getPayload().get("kcBoss").getAsString());
	}

	@Test
	public void aCountAfterTheChestCarriesTheLoot()
	{
		OutboxEntry chest = loot("Barrows", 250_000);
		OutboxEntry kill = kc("Barrows", 50);

		linker.link(chest);
		now += 100;
		linker.link(kill);

		assertEquals(chest.getId(), kill.getPayload().get("lootEventId").getAsString());
		assertEquals(250_000, kill.getPayload().get("lootValue").getAsLong());
	}

	@Test
	public void linksEachKillOnlyOnce()
	{
		OutboxEntry kill = kc("Vorkath", 101);
		OutboxEntry first = loot("Vorkath", 10);
		OutboxEntry second = loot("Vorkath", 20);

		linker.link(kill);
		linker.link(first);
		linker.link(second);

		assertFalse(second.getPayload().has("kc"));
	}

	@Test
	public void ignoresAKillFromTooLongAgo()
	{
		OutboxEntry kill = kc("Vorkath", 101);
		OutboxEntry drop = loot("Vorkath", 10);

		linker.link(kill);
		now += KillLootLinker.KC_BEFORE_LOOT_MS + 1;
		linker.link(drop);

		assertFalse(drop.getPayload().has("kc"));
	}

	@Test
	public void doesNotLinkDifferentBosses()
	{
		OutboxEntry kill = kc("Vorkath", 101);
		OutboxEntry drop = loot("Zulrah", 10);

		linker.link(kill);
		linker.link(drop);

		assertFalse(drop.getPayload().has("kc"));
	}

	@Test
	public void normalisesNamesAcrossKcAndLoot()
	{
		assertEquals("gauntlet", KillLootLinker.normalise("The Gauntlet"));
		assertEquals("gauntlet", KillLootLinker.normalise("Gauntlet"));
		assertEquals("chambers of xeric", KillLootLinker.normalise("Chambers of Xeric Challenge Mode"));
		assertEquals("tombs of amascut", KillLootLinker.normalise("Tombs of Amascut: Expert Mode"));
	}
}

