import net.runelite.client.util.Filepath;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class OutboxTest
{
	private static final AccountIdentity MAIN = new AccountIdentity("123", "Iron Dude");
	private static final AccountIdentity ALT = new AccountIdentity("456", "Iron Alt");

	private final Gson gson = new Gson();
	private final List<String> messages = new ArrayList<>();
	private final List<List<OutboxEntry>> sent = new ArrayList<>();
	private MutableClock clock;
	private Filepath file;
	private ApiException nextFailure;

	@Before
	public void setUp() throws Exception
	{
		clock = new MutableClock();
		file = Filepath.Unchecked.getRooted(Files.createTempDirectory("outbox")).join("outbox.json");
		nextFailure = null;
	}

	private Outbox outbox()
	{
		return new Outbox(this::send, new OutboxStore(file, gson), clock, messages::add);
	}

	private Outbox.SendResult send(AccountIdentity account, List<OutboxEntry> batch) throws ApiException
	{
		if (nextFailure != null)
		{
			throw nextFailure;
		}
		sent.add(batch);
		Set<String> ids = batch.stream().map(OutboxEntry::getId).collect(Collectors.toSet());
		return new Outbox.SendResult(ids, Collections.emptyMap(), Collections.singletonList("ok"));
	}

	private static OutboxEntry entry(AccountIdentity account)
	{
		return OutboxEntry.create("loot", new JsonObject(), account, Instant.EPOCH);
	}

	@Test
	public void sendsAndRemovesAcceptedEvents()
	{
		Outbox outbox = outbox();
		outbox.enqueue(entry(MAIN));
		outbox.enqueue(entry(MAIN));

		outbox.flush();

		assertEquals(1, sent.size());
		assertEquals(2, sent.get(0).size());
		assertEquals(0, outbox.size());
		assertEquals(Collections.singletonList("ok"), messages);
	}

	@Test
	public void survivesARestart()
	{
		outbox().enqueue(entry(MAIN));

		Outbox reloaded = outbox();

		assertEquals(1, reloaded.size());
		assertEquals(MAIN, reloaded.peekAll().get(0).getAccount());
	}

	@Test
	public void batchesOneAccountAtATime()
	{
		Outbox outbox = outbox();
		outbox.enqueue(entry(MAIN));
		outbox.enqueue(entry(ALT));
		outbox.enqueue(entry(MAIN));

		outbox.flush();

		assertEquals(2, sent.get(0).size());
		assertTrue(sent.get(0).stream().allMatch(e -> e.getAccount().equals(MAIN)));
		assertEquals(1, outbox.size());
	}

	@Test
	public void backsOffOnServerErrorAndKeepsEvents()
	{
		Outbox outbox = outbox();
		outbox.enqueue(entry(MAIN));
		nextFailure = new ApiException(503, "down");

		outbox.flush();
		nextFailure = null;
		outbox.flush();

		assertEquals(0, sent.size());
		assertEquals(1, outbox.size());

		clock.advance(Outbox.INITIAL_BACKOFF_MS);
		outbox.flush();

		assertEquals(1, sent.size());
		assertEquals(0, outbox.size());
	}

	@Test
	public void pausesOnBadTokenUntilResumed()
	{
		Outbox outbox = outbox();
		outbox.enqueue(entry(MAIN));
		nextFailure = new ApiException(401, "bad token");

		outbox.flush();
		nextFailure = null;
		clock.advance(Outbox.MAX_BACKOFF_MS);
		outbox.flush();

		assertTrue(outbox.isPaused());
		assertEquals(1, outbox.size());

		outbox.resume();
		outbox.flush();

		assertEquals(0, outbox.size());
	}

	@Test
	public void holdsEventsWhenThePluginIsOutdated()
	{
		Outbox outbox = outbox();
		outbox.enqueue(entry(MAIN));
		nextFailure = new ApiException(426, "update");

		outbox.flush();

		assertTrue(outbox.isPaused());
		assertEquals(1, outbox.size());
	}

	@Test
	public void discardsABatchTheServerCannotParse()
	{
		Outbox outbox = outbox();
		outbox.enqueue(entry(MAIN));
		nextFailure = new ApiException(400, "malformed");

		outbox.flush();

		assertEquals(0, outbox.size());
	}

	@Test
	public void dropsServerRejectedEventsButKeepsUnanswered()
	{
		OutboxEntry accepted = entry(MAIN);
		OutboxEntry rejected = entry(MAIN);
		OutboxEntry unanswered = entry(MAIN);
		Outbox outbox = new Outbox(
			(account, batch) -> new Outbox.SendResult(
				new HashSet<>(Collections.singletonList(accepted.getId())),
				Map.of(rejected.getId(), "too old"),
				Collections.emptyList()),
			new OutboxStore(file, gson), clock, messages::add);
		outbox.enqueue(accepted);
		outbox.enqueue(rejected);
		outbox.enqueue(unanswered);

		outbox.flush();

		assertEquals(Collections.singletonList(unanswered.getId()),
			outbox.peekAll().stream().map(OutboxEntry::getId).collect(Collectors.toList()));
	}

	@Test
	public void capsTheQueueByDroppingTheOldest()
	{
		Outbox outbox = outbox();
		OutboxEntry first = entry(MAIN);
		outbox.enqueue(first);
		for (int i = 0; i < Outbox.MAX_ENTRIES; i++)
		{
			outbox.enqueue(entry(MAIN));
		}

		assertEquals(Outbox.MAX_ENTRIES, outbox.size());
		assertTrue(outbox.peekAll().stream().noneMatch(e -> e.getId().equals(first.getId())));
	}

	private static class MutableClock extends Clock
	{
		private long millis = 1_000_000;

		void advance(long ms)
		{
			millis += ms;
		}

		@Override
		public long millis()
		{
			return millis;
		}

		@Override
		public Instant instant()
		{
			return Instant.ofEpochMilli(millis);
		}

		@Override
		public ZoneOffset getZone()
		{
			return ZoneOffset.UTC;
		}

		@Override
		public Clock withZone(java.time.ZoneId zone)
		{
			return this;
		}
	}
}

package com.ironsgrotto.progress;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.ironsgrotto.api.ApiException;
import com.ironsgrotto.api.GrottoApiClient;
import com.ironsgrotto.session.AccountIdentity;
import java.time.Clock;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ProgressTest
{
	private static final AccountIdentity ACCOUNT = new AccountIdentity("1", "Iron Dude");

	@Test
	public void diaryTierIsTheHighestCompleted()
	{
		assertEquals("None", ProgressRules.diaryTier(new int[] {0, 0, 0, 0}));
		assertEquals("Hard", ProgressRules.diaryTier(new int[] {1, 1, 1, 0}));
		// Karamja's older varbits may read 2 when done; any non-zero counts.
		assertEquals("Medium", ProgressRules.diaryTier(new int[] {2, 2, 0, 0}));
	}

	@Test
	public void caTierFollowsPointThresholds()
	{
		int[] thresholds = {41, 161, 416, 1064, 1904, 2630};
		assertEquals("None", ProgressRules.combatAchievementTier(40, thresholds));
		assertEquals("Elite", ProgressRules.combatAchievementTier(1100, thresholds));
		assertEquals("Grandmaster", ProgressRules.combatAchievementTier(2630, thresholds));
		assertEquals("None", ProgressRules.combatAchievementTier(3000, new int[6]));
	}

	/** An API client that records what it was asked to send. */
	private static class RecordingApi extends GrottoApiClient
	{
		final List<JsonObject> sent = new ArrayList<>();
		ApiException failWith;

		RecordingApi()
		{
			super(null, new Gson(), null, null, "test");
		}

		@Override
		public JsonObject putProgress(AccountIdentity identity, JsonObject progress) throws ApiException
		{
			if (failWith != null)
			{
				throw failWith;
			}
			sent.add(progress);
			return new JsonObject();
		}
	}

	private static JsonObject skills(int total)
	{
		JsonObject skills = new JsonObject();
		skills.addProperty("totalLevel", total);
		return skills;
	}

	@Test
	public void accountTypeFollowsTheIronmanVarbit()
	{
		assertEquals("main", ProgressRules.accountType(0));
		assertEquals("ironman", ProgressRules.accountType(1));
		assertEquals("ultimate_ironman", ProgressRules.accountType(2));
		assertEquals("hardcore_ironman", ProgressRules.accountType(3));
		assertEquals("group_ironman", ProgressRules.accountType(4));
		assertEquals("hardcore_group_ironman", ProgressRules.accountType(5));
		assertEquals("unranked_group_ironman", ProgressRules.accountType(6));
		assertNull(ProgressRules.accountType(7));
	}

	@Test
	public void collectionLogChatIsBitOneOfTheSetting()
	{
		assertFalse(ProgressRules.collectionLogChatEnabled(0));
		assertTrue(ProgressRules.collectionLogChatEnabled(1));
		assertFalse(ProgressRules.collectionLogChatEnabled(2));
		assertTrue(ProgressRules.collectionLogChatEnabled(3));
	}

	@Test
	public void sendsEachCategoryOnceUntilItChanges()
	{
		RecordingApi api = new RecordingApi();
		ProgressUploader uploader = new ProgressUploader(api, Clock.systemUTC());

		uploader.submit(ACCOUNT, "skills", skills(1500));
		uploader.flush();
		uploader.submit(ACCOUNT, "skills", skills(1500));
		uploader.flush();
		uploader.submit(ACCOUNT, "skills", skills(1501));
		uploader.flush();

		assertEquals(2, api.sent.size());
		assertEquals(1501, api.sent.get(1).getAsJsonObject("skills").get("totalLevel").getAsInt());
	}

	@Test
	public void mergesCollectionLogCountsWithItsItems()
	{
		RecordingApi api = new RecordingApi();
		ProgressUploader uploader = new ProgressUploader(api, Clock.systemUTC());
		JsonObject items = new JsonObject();
		items.addProperty("complete", true);
		JsonObject counts = new JsonObject();
		counts.addProperty("obtained", 500);

		uploader.submit(ACCOUNT, "collectionLog", items);
		uploader.submit(ACCOUNT, "collectionLog", counts);
		uploader.flush();

		JsonObject log = api.sent.get(0).getAsJsonObject("collectionLog");
		assertTrue(log.get("complete").getAsBoolean());
		assertEquals(500, log.get("obtained").getAsInt());
	}

	@Test
	public void keepsProgressWhenTheServerIsDown()
	{
		RecordingApi api = new RecordingApi();
		ProgressUploader uploader = new ProgressUploader(api, Clock.systemUTC());
		api.failWith = new ApiException(503, "down");

		uploader.submit(ACCOUNT, "skills", skills(1500));
		uploader.flush();

		assertTrue(uploader.hasPending());
	}

	@Test
	public void dropsProgressTheServerRejects()
	{
		RecordingApi api = new RecordingApi();
		ProgressUploader uploader = new ProgressUploader(api, Clock.systemUTC());
		api.failWith = new ApiException(400, "bad");

		uploader.submit(ACCOUNT, "skills", skills(1500));
		uploader.flush();

		assertFalse(uploader.hasPending());
	}

	@Test
	public void tellsWhichUploadsCarriedTheFullLog()
	{
		RecordingApi api = new RecordingApi();
		ProgressUploader uploader = new ProgressUploader(api, Clock.systemUTC());
		List<JsonObject> sent = new ArrayList<>();
		uploader.setOnSent((body, result) -> sent.add(body));
		JsonObject full = new JsonObject();
		full.addProperty("complete", true);

		assertTrue(uploader.submit(ACCOUNT, "collectionLog", full));
		uploader.flush();
		// The same log again: nothing to send, so the caller knows it's already there.
		assertFalse(uploader.submit(ACCOUNT, "collectionLog", full));

		assertEquals(1, sent.size());
		assertTrue(ProgressSync.isFullLog(sent.get(0)));
		JsonObject countsOnly = new JsonObject();
		countsOnly.add("collectionLog", new JsonObject());
		assertFalse(ProgressSync.isFullLog(countsOnly));
		assertFalse(ProgressSync.isFullLog(new JsonObject()));
	}

	@Test
	public void saysWhatAFullLogSyncChanged()
	{
		JsonObject reply = new JsonObject();
		assertNull(ProgressSync.newCollectionLogItems(reply));
		assertEquals("Collection log synced.", CollectionLogSync.sentMessage(null));

		JsonArray names = new JsonArray();
		reply.add("newCollectionLogItems", names);
		assertEquals("Collection log up to date.", CollectionLogSync.sentMessage(ProgressSync.newCollectionLogItems(reply)));

		names.add("Dragon pickaxe");
		assertEquals("Collection log updated: 1 new item.", CollectionLogSync.sentMessage(ProgressSync.newCollectionLogItems(reply)));
		names.add("Pet snakeling");
		assertEquals("Collection log updated: 2 new items.", CollectionLogSync.sentMessage(ProgressSync.newCollectionLogItems(reply)));
	}

	@Test
	public void reportsARefusedUploadButNotARetriedOne()
	{
		RecordingApi api = new RecordingApi();
		ProgressUploader uploader = new ProgressUploader(api, Clock.systemUTC());
		List<JsonObject> dropped = new ArrayList<>();
		uploader.setOnDropped(dropped::add);

		api.failWith = new ApiException(503, "down");
		uploader.submit(ACCOUNT, "skills", skills(1500));
		uploader.flush();
		assertTrue(dropped.isEmpty());

		RecordingApi refusing = new RecordingApi();
		ProgressUploader other = new ProgressUploader(refusing, Clock.systemUTC());
		other.setOnDropped(dropped::add);
		refusing.failWith = new ApiException(400, "bad");
		other.submit(ACCOUNT, "skills", skills(1500));
		other.flush();
		assertEquals(1, dropped.size());
	}
}

package com.ironsgrotto.tracker;

import java.util.Optional;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

public class ChatMessageParserTest
{
	private static void assertKc(String message, String boss, int kc)
	{
		Optional<ChatMessageParser.KillCount> parsed = ChatMessageParser.killCount(message);
		assertEquals(message, Optional.of(new ChatMessageParser.KillCount(boss, kc)), parsed);
	}

	@Test
	public void readsKillCounts()
	{
		assertKc("Your Vorkath kill count is: 123.", "Vorkath", 123);
		assertKc("Your TzTok-Jad kill count is: 1.", "TzTok-Jad", 1);
		assertKc("Your completed Chambers of Xeric count is: 5.", "Chambers of Xeric", 5);
		assertKc("Your completed Theatre of Blood: Hard Mode count is: 12.", "Theatre of Blood: Hard Mode", 12);
		assertKc("Your Barrows chest count is: 1,234.", "Barrows", 1234);
		assertKc("Your subdued Wintertodt count is: 10.", "Wintertodt", 10);
		assertKc("Your Gauntlet completion count is: 3.", "Gauntlet", 3);
		assertKc("Your Tombs of Amascut: Expert Mode total completion count is: 7.", "Tombs of Amascut: Expert Mode", 7);
	}

	@Test
	public void ignoresLapsAndOtherMessages()
	{
		assertFalse(ChatMessageParser.killCount("Your Ardougne Rooftop lap count is: 4.").isPresent());
		assertFalse(ChatMessageParser.killCount("Fight duration: 1:23. Personal best: 1:10").isPresent());
		assertFalse(ChatMessageParser.killCount("Your Vorkath kill count is: 0.").isPresent());
	}

	@Test
	public void readsCollectionLogSlots()
	{
		assertEquals(Optional.of("Vorki"), ChatMessageParser.collectionLogItem("New item added to your collection log: Vorki"));
		assertEquals(Optional.of("Dragon warhammer"), ChatMessageParser.collectionLogItem("New item added to your collection log: Dragon warhammer."));
		assertFalse(ChatMessageParser.collectionLogItem("Welcome to Old School RuneScape.").isPresent());
	}

	@Test
	public void readsPetMessages()
	{
		assertEquals(Optional.of("follower"), ChatMessageParser.petVariant("You have a funny feeling like you're being followed."));
		assertEquals(Optional.of("backpack"), ChatMessageParser.petVariant("You feel something weird sneaking into your backpack."));
		assertEquals(Optional.of("duplicate"), ChatMessageParser.petVariant("You have a funny feeling like you would have been followed..."));
		assertFalse(ChatMessageParser.petVariant("You feel a funny feeling.").isPresent());
	}

	@Test
	public void readsClueCounts()
	{
		assertEquals(Optional.of(new ChatMessageParser.ClueCount("Hard", 12)), ChatMessageParser.clueCount("You have completed 12 hard Treasure Trails."));
		assertEquals(Optional.of(new ChatMessageParser.ClueCount("Beginner", 1)), ChatMessageParser.clueCount("You have completed 1 beginner Treasure Trail."));
		assertEquals(Optional.of(new ChatMessageParser.ClueCount("Master", 1234)), ChatMessageParser.clueCount("You have completed 1,234 master Treasure Trails."));
		assertFalse(ChatMessageParser.clueCount("You have completed the Treasure Trail.").isPresent());
	}
}

package com.ironsgrotto.tracker;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import net.runelite.http.api.loottracker.LootRecordType;
import org.junit.Test;

public class LootEventTrackerTest
{
	@Test
	public void skipsSailingSalvage()
	{
		assertTrue(LootEventTracker.isIgnored(LootRecordType.EVENT, "Opulent salvage"));
		assertTrue(LootEventTracker.isIgnored(LootRecordType.EVENT, "Fishy salvage"));
	}

	@Test
	public void keepsOtherLoot()
	{
		assertFalse(LootEventTracker.isIgnored(LootRecordType.EVENT, "Bird nest"));
		assertFalse(LootEventTracker.isIgnored(LootRecordType.EVENT, "Chambers of Xeric"));
		assertFalse(LootEventTracker.isIgnored(LootRecordType.NPC, "Opulent salvage"));
		assertFalse(LootEventTracker.isIgnored(LootRecordType.EVENT, null));
	}

	@Test
	public void recognisesPickpocketMessages()
	{
		assertTrue(LootEventTracker.isPickpocket("You pick the H.A.M. Member's pocket."));
		assertTrue(LootEventTracker.isPickpocket("You pick the Master Farmer's pocket."));
		assertFalse(LootEventTracker.isPickpocket("You fail to pick the Master Farmer's pocket."));
		assertFalse(LootEventTracker.isPickpocket("Your Maggot King kill count is: 673."));
	}
}

package com.ironsgrotto.ui;

import static org.junit.Assert.assertEquals;

import org.junit.Test;

public class ClanEventOverlayTest
{
	private static final int LINE = 16;

	@Test
	public void showsTheDefaultUntilResized()
	{
		assertEquals(ClanEventOverlay.DEFAULT_ROWS, ClanEventOverlay.rowsFor(0, LINE, 25));
	}

	@Test
	public void taller_showsMore()
	{
		int threeRows = ClanEventOverlay.rowsFor(10 + 5 * LINE, LINE, 25);
		int sevenRows = ClanEventOverlay.rowsFor(10 + 9 * LINE, LINE, 25);
		assertEquals(3, threeRows);
		assertEquals(7, sevenRows);
	}

	@Test
	public void neverMoreThanThereAre_neverNone()
	{
		assertEquals(4, ClanEventOverlay.rowsFor(2000, LINE, 4));
		assertEquals(1, ClanEventOverlay.rowsFor(20, LINE, 25));
		assertEquals(0, ClanEventOverlay.rowsFor(500, LINE, 0));
		assertEquals(2, ClanEventOverlay.rowsFor(0, LINE, 2));
	}
}

package com.ironsgrotto.ui;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class GrottoPanelTest
{
	@Test
	public void tokenLinkNamesTheAccount()
	{
		assertEquals("https://ironsgrotto.xyz/plugin?name=Eclipse%20Goon",
			GrottoPanel.tokenUrlFor("https://ironsgrotto.xyz/plugin", "Eclipse Goon"));
	}

	@Test
	public void onlyAWholeTokenIsChecked()
	{
		String token = "igp_" + "a".repeat(40) + "_-9";
		assertTrue(GrottoPanel.looksLikeToken(token));
		assertFalse(GrottoPanel.looksLikeToken(token.substring(0, 30)));
		assertFalse(GrottoPanel.looksLikeToken("abc_" + "a".repeat(43)));
		assertFalse(GrottoPanel.looksLikeToken(token + "x"));
	}

	@Test
	public void shortGpReadsLikeOsrsValues()
	{
		assertEquals("950", GrottoPanel.shortGp(950));
		assertEquals("1K", GrottoPanel.shortGp(1_000));
		assertEquals("952K", GrottoPanel.shortGp(952_409));
		assertEquals("999K", GrottoPanel.shortGp(999_999));
		assertEquals("1.25M", GrottoPanel.shortGp(1_255_777));
		assertEquals("42.8M", GrottoPanel.shortGp(42_820_578));
		assertEquals("42M", GrottoPanel.shortGp(42_065_000));
		assertEquals("2.14B", GrottoPanel.shortGp(2_147_483_647L));
	}

	@Test
	public void agoIsOneShortWord()
	{
		java.time.Instant now = java.time.Instant.parse("2026-10-02T12:00:00Z");
		assertEquals("now", GrottoPanel.ago("2026-10-02T11:59:30Z", now));
		assertEquals("45m", GrottoPanel.ago("2026-10-02T11:15:00Z", now));
		assertEquals("3h", GrottoPanel.ago("2026-10-02T09:00:00Z", now));
		assertEquals("2d", GrottoPanel.ago("2026-09-30T11:00:00Z", now));
		assertEquals("3w", GrottoPanel.ago("2026-09-10T12:00:00Z", now));
		assertEquals("", GrottoPanel.ago("not a date", now));
	}
}
